(() => {
  'use strict';
  const root=document.getElementById('wiki22-cultura'), content=root.querySelector('#w-content'), feedback=root.querySelector('#w-feedback');
  const token=document.querySelector('meta[name="wiki22-token"]').content;
  const state={libraries:[],prefs:{mode:'UNIFIED',ids:[],columns:true,font_size:17},view:'home',document:null,page:0,note:null,rows:[],suggestions:[],next:null,query:'',shelf:[],shelfSelection:[],researches:[],research:null,researchPage:0,researchNote:null,removal:null,generation:0,importing:false,comparison:null,compareChoices:[],compareQuery:'',compareSearched:false,combined:false,commonOnly:false,timeline:null};
  const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const countLabel=n=>n.toLocaleString('it-IT')+(n===1?' voce':' voci');
  const library=id=>state.libraries.find(l=>l.id===id);
  const names=ids=>ids.map(id=>library(id)?.name||'Libreria non disponibile').join(' + ');
  const selected=()=>state.prefs.mode==='UNIFIED'?state.libraries.filter(l=>l.enabled).map(l=>l.id):state.prefs.ids;
  const scope=()=>({mode:state.prefs.mode,ids:selected()});
  async function api(path,value={}){
    const response=await fetch('/api/'+path,{method:'POST',headers:{'Content-Type':'application/json','X-Wiki22-Token':token},body:JSON.stringify(value)});
    const body=await response.json();if(!response.ok)throw new Error(body.error||'Operazione non riuscita.');return body;
  }
  function message(text,error=false){feedback.setAttribute('role',error?'alert':'status');feedback.textContent=text;feedback.className=error?'w-message w-error':'w-message';}
  function shell(){
    root.querySelector('#w-mode').value=state.prefs.mode;
    const researching=state.view==='research';
    const input=root.querySelector('#w-search');input.placeholder=researching?'Aggiungi un argomento alla ricerca…':'Cerca un argomento, un autore, un luogo…';input.setAttribute('aria-label',researching?'Aggiungi un argomento alla ricerca':'Cerca un argomento');
    input.disabled=researching&&(state.researchBusy||state.research?.documents.length>=12);
    root.querySelector('#w-searchbutton').textContent=researching?'Aggiungi argomento':'Cerca';root.querySelector('#w-searchbutton').disabled=input.disabled;
    if(state.view==='places'){input.placeholder='Cerca un Paese o una città…';input.setAttribute('aria-label','Cerca un Paese o una città');root.querySelector('#w-searchbutton').textContent='Cerca luogo';}
    const ids=selected();root.querySelector('#w-librarylist').innerHTML=state.libraries.filter(l=>l.enabled).map(l=>`<label class="w-librow"><input type="${state.prefs.mode==='SINGLE'?'radio':'checkbox'}" name="library" data-library="${esc(l.id)}" ${ids.includes(l.id)?'checked':''}><span>${esc(l.name)}<small>${Number.isInteger(l.articles)?countLabel(l.articles):esc(l.source)}</small></span></label>`).join('');
    root.querySelector('#w-scope').textContent=ids.length?(state.prefs.mode==='UNIFIED'?'Tutte le librerie':ids.length===1?'Una libreria':ids.length+' librerie selezionate')+' · '+names(ids):'Seleziona una libreria per iniziare.';
    root.querySelectorAll('[data-nav]').forEach(b=>{if(b.dataset.nav===(state.view==='article'?'home':state.view==='research'?'shelf':state.view))b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});
    root.style.setProperty('--reading-size',state.prefs.font_size+'px');
    root.dataset.palette=state.prefs.palette||'paper';document.body.dataset.palette=root.dataset.palette;
    root.style.setProperty('--reading-font',state.prefs.reading_font==='sans'?'Arial, sans-serif':'Georgia, serif');
    root.style.setProperty('--reading-leading',state.prefs.line_spacing==='airy'?'2.1':'1.8');
  }
  function cards(rows, shelf=false){return `<div class="w-cardlist">${rows.map((r,i)=>`<button class="w-result" data-${shelf?'resume':'result'}="${i}"><span><strong>${esc(r.title)}</strong><small>${esc(r.library_name||names([r.library_id]))}${shelf?' · Riprendi da pagina '+(r.page+1):''}</small></span><span aria-hidden="true">↗</span></button>`).join('')}</div>`;}
  function home(){if(!state.libraries.some(l=>l.enabled)){emptyHome();return;}content.innerHTML=`<section class="w-page w-home"><div class="w-breadcrumb">La tua biblioteca, nuove prospettive</div><h1>La conoscenza prende forma.</h1><p class="w-deck">Cerca un argomento nella barra in alto. Leggi le fonti, unisci le voci e segui i legami nel tempo.</p><div class="w-home-paths"><button data-nav="explore"><span class="w-label">01 · Scopri</span><strong>Esplora</strong><span>Percorsi per categorie, idee e argomenti da avvicinare.</span><b>Segui un percorso ↗</b></button><button data-nav="timeline"><span class="w-label">02 · Contestualizza</span><strong>Linea del tempo</strong><span>Un anno, un mese, un giorno. Ritrova gli eventi nelle tue fonti.</span><b>Esplora una data ↗</b></button><button data-nav="shelf"><span class="w-label">03 · Collega</span><strong>Il mio scaffale</strong><span>Riprendi le letture e riunisci le voci in una ricerca unica.</span><b>Apri lo scaffale ↗</b></button></div>${state.shelf.length?'<section class="w-home-recent"><h2>Riprendi da dove eri</h2>'+cards(state.shelf.slice(0,4),true)+'</section>':'<p class="w-empty">Le tue letture salvate compariranno qui. Usa «Salva nello scaffale» mentre leggi una voce.</p>'}<section class="w-home-topics"><h2>Un punto di partenza</h2><div class="w-topiclist">${['Italia','Rinascimento','Filosofia','Scienza','Letteratura','Musica'].map(q=>`<button data-topic="${q}">${q} ↗</button>`).join('')}</div></section><footer class="w-home-library"><div><h3>La conoscenza che scegli tu</h3><p>Usa una libreria, alcune o tutte insieme. Aggiungi i tuoi libri e le tue raccolte.</p></div><button data-nav="libraries">Gestisci e importa librerie</button></footer></section>`;}

  function searchView(){
    const alpha='';
    content.innerHTML=`<section class="w-page"><div class="w-breadcrumb">Voci dalle librerie selezionate</div><h1>Risultati</h1>${state.query?`<p class="w-deck">${esc(state.query)}</p>`:''}${alpha}${state.rows.length?cards(state.rows):'<p class="w-empty">Nessuna voce trovata. Prova il nome dell’argomento o cambia le librerie selezionate.</p>'}${state.suggestions.length?'<h2>Titoli simili · Forse cercavi…</h2>'+cards(state.suggestions).replaceAll('data-result=','data-alternative='):''}${state.next?'<div class="w-related"><button data-action="more">Mostra altre voci</button></div>':''}</section>`;
  }
  function renderArticle(){
    const d=state.document;if(!d)return;state.page=Math.max(0,Math.min(state.page,d.pages.length-1));const blocks=d.pages[state.page];
    const note=state.note?d.notes[state.note-1]:null;
    const noteHtml=note?`<aside class="w-source" aria-label="Dettaglio della fonte"><div class="w-sourcehead"><div><div class="w-label">Fonte ${note.number}</div><h3>${esc(d.library_name)} · ${esc(note.heading)}</h3></div><button data-action="close-source" aria-label="Chiudi fonte">×</button></div><blockquote>${esc(note.excerpt)}</blockquote><div class="w-note-meta"><span>${esc(note.source)}</span>${note.revision?' · Revisione '+esc(note.revision):''}${note.revision_url?.startsWith('https://it.wikipedia.org/')?`<a href="${esc(note.revision_url)}" target="_blank" rel="noreferrer noopener">Originale online ↗</a>`:''}</div><details><summary>Leggi il contesto</summary><p class="w-note-context">${esc(note.context)}</p></details></aside>`:'';
    content.innerHTML=`<article class="w-page"><div class="w-breadcrumb">${esc(d.library_name)}</div><h1>${esc(d.title)}</h1><p class="w-small">${esc(d.reading_kind)}${d.library_name==='Wikipedia italiana'?' · Wikipedia, CC BY-SA':''}</p><div class="w-actions">${state.research?'<button data-action="return-research">← Ricerca aperta</button>':''}<button data-action="results">Risultati</button><button data-action="bookmark" aria-pressed="${d.saved}">${d.saved?'✓ Nello scaffale':'＋ Salva nello scaffale'}</button><button data-action="extend-article">Estendi la ricerca</button><button data-action="sources">Fonti della pagina</button><button data-action="compare">Confronta librerie</button><button data-action="timeline">Linea del tempo</button><button data-action="export">Esporta per leggere o stampare</button></div><details class="w-source-tools"><summary>Strumenti sulla fonte</summary><div class="w-row"><button data-action="observe">Osserva questa fonte</button><button data-action="reason">Interroga la voce</button></div></details>${d.presentation&&(d.presentation.omitted.length||d.presentation.formatted_sentences)?`<details class="w-source-tools"><summary>Testo e fedeltà alla fonte</summary><p class="w-small">${esc(d.presentation.method)}</p>${d.presentation.omitted.length?`<details><summary>Passaggi esclusi dalla lettura · ${d.presentation.omitted.length}</summary>${d.presentation.omitted.map(o=>{const n=d.notes[o.note-1];return `<blockquote><small>Fonte [${n.number}] · ${esc(o.reason)} · ${esc(n.heading)}</small><p>${esc(n.excerpt)}</p></blockquote>`;}).join('')}</details>`:''}</details>`:''}<nav class="w-toc" aria-label="Indice della voce"><details><summary>Indice della voce · ${d.toc.length} ${d.toc.length===1?'sezione':'sezioni'}</summary><div>${d.toc.map(t=>`<button data-page="${t.page}">${esc(t.heading)}</button>`).join('')}</div></details></nav>${d.overview?`<p class="w-deck">${esc(d.overview)}</p>`:''}${d.themes?.length&&d.unconnected?.length?`<p class="w-small">Non sono emersi temi condivisi sufficienti per includere: ${d.unconnected.map(esc).join(', ')}. Puoi consultare le voci originali dai nomi in alto.</p>`:''}<div class="w-copy w-research-copy" data-columns="${state.prefs.columns?2:1}">${blocks.map((b,i)=>`<section>${i===0||blocks[i-1].heading!==b.heading?`<h3>${esc(b.heading)}</h3>`:''}<p>${b.sentences.map(s=>`${esc(s.text)}<button class="w-cite" data-note="${s.note}" aria-label="Apri fonte ${s.note}">[${s.note}]</button> `).join('')}</p></section>`).join('')}</div>${noteHtml}<footer class="w-bottom"><button data-action="previous" ${state.page===0?'disabled':''}>← Precedente</button><label>Pagina <input id="w-page-number" aria-label="Numero di pagina" type="number" min="1" max="${d.pages.length}" value="${state.page+1}"> di ${d.pages.length}</label><button data-action="next" ${state.page===d.pages.length-1?'disabled':''}>Successiva →</button></footer></article>${d.related.length?`<div class="w-related"><span class="w-small">Continua la lettura</span>${d.related.map(t=>`<button data-topic="${esc(t)}">${esc(t)} ↗</button>`).join('')}</div>`:''}`;
  }
  function renderLibraries(){content.innerHTML=`<section class="w-page"><div class="w-breadcrumb">Le tue fonti</div><h1>Librerie</h1><p class="w-deck">Wikipedia, le tue raccolte e i tuoi testi. Separati all’origine, consultabili insieme.</p><div class="w-actions"><button data-nav="catalog">Scarica Wikipedia</button><button data-nav="probe">Crea con la sonda</button></div><h2>Gestisci le tue librerie</h2><p class="w-small">Rimuovi una libreria per escluderla dalle ricerche. Puoi ripristinarla: file originali, raccolte 22CK e scaffale restano conservati. La rimozione non libera spazio su disco.</p>${libraryCards(state.libraries.filter(l=>!l.removed))}<details class="w-library-trash"><summary>Cestino delle librerie · ${state.libraries.filter(l=>l.removed).length}</summary>${libraryCards(state.libraries.filter(l=>l.removed),true)}</details><section class="w-import"><h3>Importa una raccolta</h3><label>Nome della libreria<input id="w-import-name" type="text" maxlength="80" placeholder="Ad esempio: Storia dell’arte"></label><label>Percorso del file o della cartella<input id="w-import-path" type="text" placeholder="Scegli dal computer oppure incolla il percorso"></label><div class="w-row"><button data-pick="folder">Scegli cartella…</button><button data-pick="file">Scegli file…</button><button class="w-primary" data-action="import" ${state.importing?'disabled':''}>${state.importing?'Importazione in corso…':'Importa libreria'}</button></div><p class="w-small">Conversione locale in 22CK: PDF con testo, EPUB, DOCX, ODT, FB2, PPTX, HTML, TXT, Markdown, CSV, TSV e JSON. Le sottocartelle sono incluse; gli originali restano invariati. Immagini e impaginazione non sono riprodotte. PDF scansiti: serve OCR esterno. MOBI/AZW/AZW3: richiedono Calibre; DRM non supportato.</p><button data-action="formats">Verifica formati e convertitori disponibili</button></section>${reportHtml()}</section>`;}
  function libraryCards(rows,removed=false){return `<div class="w-cardlist">${rows.map(l=>{const i=state.libraries.indexOf(l);return `<article class="w-import w-librarycard"><div><h3>${esc(l.name)}</h3><p class="w-small">${Number.isInteger(l.articles)?countLabel(l.articles)+' · ':''}${esc(l.source)}</p>${removed?'<small>Esclusa dalle ricerche. File e letture salvate conservati.</small>':`<label>Nome<input id="w-library-name-${i}" aria-label="Nome della libreria ${esc(l.name)}" type="text" maxlength="80" value="${esc(l.name)}"></label>`}</div><div class="w-row">${removed?`<button data-lib-restore="${i}">Ripristina</button>`:`<button data-lib-rename="${i}">Salva nome</button>${l.enabled?`<button data-only="${esc(l.id)}">Usa solo questa</button>`:''}<button data-lib-remove="${i}">Rimuovi</button>`}</div></article>`;}).join('')||'<p class="w-empty">Nessuna libreria. Importa una raccolta o ripristinala dal cestino.</p>'}</div>`;}
  async function manageLibrary(i,action){
    if(state.libraryBusy)return;const l=state.libraries[i];state.libraryBusy=true;const generation=++state.generation;
    const name=content.querySelector('#w-library-name-'+i)?.value;message('Aggiorno la libreria…');
    try{const r=await api('library/manage',{library_id:l.id,action,name});state.libraries=r.libraries;state.prefs=r.preferences;state.document=null;state.research=null;state.comparison=null;state.timeline=null;state.places=null;state.placeRows=[];state.placeQuery='';state.shelfSelection=[];
      if(generation===state.generation){render();message(action==='remove'?`«${r.name}» rimossa. Puoi ripristinarla dal cestino; nessun file è stato cancellato.`:action==='restore'?`«${r.name}» ripristinata.`:'Nome aggiornato.');}
    }finally{state.libraryBusy=false;}
  }
  function renderPlaces(){const p=state.places;content.innerHTML=`<section class="w-page"><div class="w-breadcrumb">Conoscere un territorio</div><h1>Paesi e città</h1><p class="w-deck">Cerca un luogo nella barra in alto. Scegli la voce e costruisci una lettura con la sua storia, geografia e cultura.</p>${!p?`<div class="w-topiclist">${['Italia','Svizzera','Roma','Firenze','Parigi'].map(q=>`<button data-place-topic="${q}">${q} ↗</button>`).join('')}</div><h2>${state.placeQuery?'Scegli la voce del luogo':'Da quale luogo vuoi partire?'}</h2><div class="w-cardlist">${(state.placeRows||[]).map((r,i)=>`<button class="w-result" data-place-choice="${i}"><span><strong>${esc(r.title)}</strong><small>${esc(r.library_name)}</small></span><span>Esplora ↗</span></button>`).join('')|| (state.placeQuery?'<p>Nessuna voce disponibile. Prova un nome più preciso o cambia le librerie.</p>':'')}</div>`:`<h2>${esc(p.title)}</h2><p class="w-small">${esc(p.method)}</p>${p.limited?'<p class="w-small">Selezione limitata ai primi titoli pertinenti. Puoi aggiungere altri argomenti nella ricerca.</p>':''}<div class="w-row"><button class="w-primary" data-action="compose-place" ${!state.placeSelection?.length||state.placeBusy?'disabled':''}>Crea ricerca sul luogo</button><span>${state.placeSelection?.length||0}/12 voci selezionate</span></div><div class="w-cardlist">${p.rows.map((r,i)=>`<article class="w-place-row"><label><input type="checkbox" data-place-check="${i}" ${state.placeSelection.includes(i)?'checked':''}><span><strong>${esc(r.title)}</strong><small>${esc(r.theme)} · ${esc(r.library_name)}</small></span></label><button data-place-read="${i}">Leggi ↗</button></article>`).join('')}</div>`}</section>`;}
  async function searchPlaces(query){cancelLiveSearch();const generation=++state.generation;state.placeQuery=query.trim();state.places=null;state.placeRows=[];renderPlaces();if(!state.placeQuery)return;message('Cerco il luogo nelle librerie selezionate…');const r=await api('search',{query:state.placeQuery,limit:12,...scope()});if(generation!==state.generation)return;state.placeRows=r.rows.length?r.rows:r.suggestions||[];renderPlaces();message('');}
  async function resolvePlace(i){const generation=++state.generation;message('Preparo le letture sul luogo…');const row=state.placeRows[i];const r=await api('places/resolve',{library_id:row.library_id,article_id:row.article_id,...scope()});if(generation!==state.generation)return;state.places=r;state.placeSelection=r.rows.map((row,i)=>i).filter(i=>r.rows.findIndex(row=>row.theme===r.rows[i].theme)===i).slice(0,3);renderPlaces();message('');}
  async function composePlace(){if(state.placeBusy||!state.placeSelection?.length)return;state.placeBusy=true;const generation=++state.generation;renderPlaces();message('Riunisco le fonti del luogo…');try{const r=await api('research',{documents:state.placeSelection.map(i=>reference(state.places.rows[i])),depth:state.prefs.research_depth||'essential',...scope()});if(generation!==state.generation)return;resetKeywords();state.research=r;state.document=null;state.researchPage=0;state.researchNote=null;state.researchView='reading';state.view='research';render();message('');}finally{state.placeBusy=false;if(state.view==='places')renderPlaces();}}

  function settings(){content.innerHTML=`<section class="w-page"><div class="w-breadcrumb">Il tuo modo di leggere e approfondire</div><h1>Lettura</h1><p class="w-deck">Scegli la quantità di contenuto e il comfort della pagina.</p>${state.document&&!state.research?'<div class="w-actions"><button data-action="back-reading">← Torna alla lettura aperta</button></div>':''}<section class="w-settings-section"><h2>Ampiezza delle ricerche</h2><label class="w-setting">Per le nuove ricerche ${depthSelect(state.prefs.research_depth||'essential','w-default-depth')}</label><div class="w-depth-guide"><p><strong>Essenziale</strong><br>Una prima lettura dei temi principali.</p><p><strong>Estesa</strong><br>Più temi e più paragrafi per ogni fonte.</p><p><strong>Approfondita</strong><br>La selezione più ampia disponibile, entro i limiti di lettura del motore.</p></div><p class="w-small">Il numero di pagine dipende dalle fonti: aumentare l’ampiezza non inventa contenuti. Le ricerche salvate conservano la propria ampiezza; puoi cambiarla nella ricerca aperta.</p>${state.research?`<div class="w-row"><button data-action="return-research">Torna alla ricerca aperta</button><button data-action="apply-depth">Applica questa ampiezza alla ricerca aperta</button></div>`:''}</section><section class="w-settings-section"><h2>Comfort di lettura</h2><label class="w-setting"><input id="w-columns" type="checkbox" ${state.prefs.columns?'checked':''}>Pagina a due colonne</label><label class="w-setting">Dimensione del testo<select id="w-font">${[16,17,19,21].map(n=>`<option value="${n}" ${state.prefs.font_size===n?'selected':''}>${n===16?'Compatta':n===17?'Normale':n===19?'Grande':'Molto grande'}</option>`).join('')}</select></label><label class="w-setting">Carattere<select id="w-reading-font"><option value="serif" ${state.prefs.reading_font!=='sans'?'selected':''}>Classico · con grazie</option><option value="sans" ${state.prefs.reading_font==='sans'?'selected':''}>Lineare · senza grazie</option></select></label><label class="w-setting">Spaziatura tra le righe<select id="w-line-spacing"><option value="normal" ${state.prefs.line_spacing!=='airy'?'selected':''}>Normale</option><option value="airy" ${state.prefs.line_spacing==='airy'?'selected':''}>Ariosa</option></select></label><fieldset class="w-palette"><legend>Colori della pagina</legend>${[['paper','Carta','Chiara e neutra'],['sand','Sabbia','Toni caldi'],['mist','Nebbia','Toni freddi']].map(([v,label,desc])=>`<label><input type="radio" name="palette" id="w-palette-${v}" data-palette="${v}" value="${v}" ${(state.prefs.palette||'paper')===v?'checked':''}><span class="w-swatch w-swatch-${v}" aria-hidden="true"></span><span><strong>${label}</strong><small>${desc}</small></span></label>`).join('')}</fieldset><div class="w-reading-preview"><span class="w-label">Anteprima</span><h3>Ogni lettura apre una prospettiva.</h3><p class="w-preview-copy">Una biblioteca raccoglie voci diverse. Leggere significa avvicinarle, riconoscere il loro contesto e tornare alle fonti per approfondire.</p></div><button data-action="reset-comfort">Ripristina l’aspetto iniziale</button><p class="w-small">Le preferenze si salvano automaticamente. Sulle finestre strette la pagina passa a una colonna.</p></section></section>`;}

  const humanBytes=n=>((n||0)/1e9).toLocaleString('it-IT',{maximumFractionDigits:2})+' GB';
  let catalogTimer=null;
  function emptyHome(){content.innerHTML=`<section class="w-page w-home"><div class="w-breadcrumb">Wiki22 · La tua biblioteca comincia qui</div><h1>Prima lo spazio.<br>Poi le tue conoscenze.</h1><p class="w-deck">Wiki22 è pronto. Scegli cosa leggere: scarica Wikipedia quando vuoi oppure crea una libreria dalle tue fonti.</p><div class="w-home-paths"><button data-nav="catalog"><span class="w-label">01 · Una raccolta pronta</span><strong>Scarica Wikipedia</strong><span>Wikipedia italiana, già convertita. Download separato, con pausa e ripresa.</span><b>Scegli dal catalogo ↗</b></button><button data-nav="probe"><span class="w-label">02 · Le tue fonti</span><strong>Apri la sonda</strong><span>Scegli cartelle, documenti o pagine web. Controlla i risultati e crea una libreria.</span><b>Esplora e raccogli ↗</b></button><button data-nav="libraries"><span class="w-label">03 · La tua biblioteca</span><strong>Gestisci le librerie</strong><span>Organizza le raccolte e scegli quali consultare insieme.</span><b>Apri le librerie ↗</b></button></div><p class="w-empty">La lettura e l’importazione dei documenti locali funzionano offline. Internet serve soltanto per i download e le fonti web che scegli.</p></section>`;}
  function renderCatalog(){const data=state.catalog, t=data?.transfer||{}, active=['downloading','verifying'].includes(t.status);content.innerHTML=`<section class="w-page"><div class="w-breadcrumb">Una raccolta alla volta</div><h1>Biblioteche da scaricare</h1><p class="w-deck">Scegli i contenuti. L’applicazione è già pronta e non deve essere scaricata di nuovo.</p>${data?data.items.map(c=>`<article class="w-import"><h2>${esc(c.name)}</h2><p>${esc(c.description)}</p><p><strong>${humanBytes(c.download_bytes)}</strong> da scaricare · ${humanBytes(c.installed_bytes)} una volta pronta</p><p class="w-small">Prevedi circa ${humanBytes(c.installed_bytes+0.8e9)} liberi durante la preparazione. Spazio disponibile: ${humanBytes(data.free_bytes)}.</p><p class="w-small">${esc(c.license)}</p>${c.installed?`<p>✓ Già presente${c.removed?' · da ripristinare in Librerie':''}</p><button data-nav="libraries">Apri Librerie</button>`:`<button class="w-primary" data-download-id="${esc(c.id)}" ${active?'disabled':''}>${c.resumable||['paused','error'].includes(t.status)?'Riprendi download':'Scarica Wikipedia'}</button>`}</article>`).join(''):'<p>Carico il catalogo…</p>'}${t.id?`<section class="w-import" aria-live="polite"><h2>${t.status==='complete'?'Pronta da leggere':t.status==='paused'?'Download in pausa':'Il tuo download'}</h2><progress max="${t.total||1}" value="${t.received||0}" aria-label="Avanzamento download"></progress><p>${humanBytes(t.received)} di ${humanBytes(t.total)}</p><p>${esc(t.message)}</p>${active?'<button data-action="download-pause">Metti in pausa</button>':''}${t.status==='complete'?'<button data-nav="home">Comincia a leggere →</button>':''}</section>`:''}<p class="w-small">I file vengono controllati prima di diventare una libreria. Se chiudi Wiki22, torna qui e premi Scarica per riprendere i dati già trasferiti.</p></section>`;}
  async function refreshCatalog(){clearTimeout(catalogTimer);state.catalog=await api('catalog');if(state.catalog.transfer.status==='complete'){const d=await api('bootstrap');state.libraries=d.libraries;}if(state.view==='catalog'){render();if(['downloading','verifying'].includes(state.catalog.transfer.status))catalogTimer=setTimeout(()=>refreshCatalog().catch(e=>message(e.message,true)),1000);}}
  function probeDraft(){return {paths:content.querySelector('#w-probe-paths')?.value||state.probePaths||'',urls:content.querySelector('#w-probe-urls')?.value||state.probeUrls||'',name:content.querySelector('#w-probe-name')?.value||state.probeName||''};}
  function renderProbe(){const p=state.probe;content.innerHTML=`<section class="w-page"><div class="w-breadcrumb">Le fonti le scegli tu</div><h1>Sonda delle fonti</h1><p class="w-deck">Da documenti e pagine web a una libreria personale, consultabile insieme alle altre.</p><section class="w-import"><h2>1. Indica dove cercare</h2><label>File e cartelle · un percorso per riga<textarea id="w-probe-paths" rows="3" placeholder="Scegli dal computer o incolla un percorso">${esc(state.probePaths||'')}</textarea></label><div class="w-row"><button data-probe-pick="folder">Scegli cartella…</button><button data-probe-pick="file">Scegli file…</button></div><label>Pagine web · un indirizzo per riga<textarea id="w-probe-urls" rows="3" placeholder="https://…">${esc(state.probeUrls||'')}</textarea></label><p class="w-small">Esplora include le sottocartelle locali e scarica solo gli indirizzi web indicati, senza seguire automaticamente i collegamenti. Usa fonti che puoi consultare e conservare; nessun accesso con account o aggiramento di protezioni. Massimo 20 indirizzi, 4 MiB per pagina.</p><button class="w-primary" data-action="probe-scan" ${state.probeBusy?'disabled':''}>${state.probeBusy?'Operazione in corso…':'Esplora le fonti'}</button></section>${p?`<section class="w-import"><h2>2. Scegli cosa includere</h2><p>${p.rows.filter(r=>r.status==='ready').length} documenti disponibili. I file originali restano al loro posto.</p><div class="w-probe-list">${p.rows.map(r=>`<label class="w-probe-source"><input type="checkbox" data-probe-source="${esc(r.id)}" ${r.status!=='ready'||state.probeBusy?'disabled':''} ${state.probeSelected?.includes(r.id)?'checked':''}><span><strong>${esc(r.label)}</strong><small>${esc(r.source)}</small><small>${r.status==='ready'?(r.bytes/1024).toFixed(1)+' KB':esc(r.reason)}</small></span></label>`).join('')||'<p>Nessun documento trovato.</p>'}</div><h2>3. Crea la libreria</h2><label>Nome della libreria<input id="w-probe-name" maxlength="80" value="${esc(state.probeName||'')}" placeholder="Ad esempio: La storia del mio territorio"></label><p class="w-small">Conversione locale con provenienza e impronta dei testi. PDF scansiti richiedono OCR; pagine dinamiche possono offrire solo una parte del testo.</p><button class="w-primary" data-action="probe-create" ${state.probeBusy?'disabled':''}>Crea libreria dalle fonti selezionate</button></section>`:''}${reportHtml()}</section>`;}
  async function scanProbe(){const d=probeDraft();state.probePaths=d.paths;state.probeUrls=d.urls;state.probeName=d.name;state.probeBusy=true;state.probe=null;render();message('Esploro soltanto le fonti indicate…');try{state.probe=await operation('probe/scan',{paths:d.paths.split('\n').map(x=>x.trim()).filter(Boolean),urls:d.urls.split('\n').map(x=>x.trim()).filter(Boolean)});state.probeSelected=state.probe.rows.filter(r=>r.status==='ready').map(r=>r.id);message('Anteprima pronta. Controlla la selezione prima di creare la libreria.');}finally{state.probeBusy=false;if(state.view==='probe')render();}}
  async function createProbe(){state.probeName=probeDraft().name;state.probeBusy=true;render();message('Creo la libreria e verifico i testi…');try{state.importReport=await operation('probe/create',{token:state.probe.token,selected:state.probeSelected,name:state.probeName});const d=await api('bootstrap');state.libraries=d.libraries;message(state.importReport.id?'Libreria creata: apri Librerie per leggerla.':'Nessun documento convertito. Consulta il rapporto.');}finally{state.probeBusy=false;if(state.view==='probe')render();}}

  function render(){shell();if(state.view==='catalog')renderCatalog();else if(state.view==='probe')renderProbe();else if(state.view==='home')home();else if(state.view==='explore')renderExplore();else if(state.view==='places')renderPlaces();else if(state.view==='article')renderArticle();else if(state.view==='compare')renderCompare();else if(state.view==='timeline')renderTimeline();else if(state.view==='graph')renderGraph();else if(state.view==='memory')renderMemory();else if(state.view==='reason')renderReason();else if(state.view==='diagnosis')renderDiagnosis();else if(state.view==='libraries')renderLibraries();else if(state.view==='about')renderAbout();else if(state.view==='settings')settings();else if(state.view==='shelf')renderShelf();else if(state.view==='research')renderResearch();else searchView();}
  const shelfKey=r=>JSON.stringify([r.library_id,r.article_id]);
  const chosenShelf=()=>state.shelf.filter(r=>state.shelfSelection.includes(shelfKey(r))&&selected().includes(r.library_id));
  async function refreshShelf(){const [rows,researches]=await Promise.all([api('shelf'),api('research/list')]);state.shelf=rows;state.researches=researches;state.shelfSelection=state.shelfSelection.filter(k=>rows.some(r=>shelfKey(r)===k));}
  function renderShelf(){
    const chosen=chosenShelf(),allowed=state.shelf.filter(r=>selected().includes(r.library_id));
    content.innerHTML=`<section class="w-page"><div class="w-breadcrumb">Le letture che vuoi ritrovare e mettere in relazione</div><h1>Il mio scaffale</h1><p class="w-deck">Scegli una o più voci: potrai ampliare la ricerca aggiungendo altre parole chiave.</p>${state.removal?`<div class="w-undo" role="status">${state.removal.removed} ${state.removal.removed===1?'elemento rimosso':'elementi rimossi'} dallo scaffale. <button data-action="undo-shelf">Annulla rimozione</button><small>Le voci nelle librerie restano disponibili.</small></div>`:''}${state.shelf.length?`<div class="w-shelf-tools"><div><strong>${chosen.length} voci selezionate</strong><small>Da 1 a 12 voci delle librerie attive</small></div><button data-action="select-shelf">${chosen.length===allowed.length&&allowed.length?'Deseleziona tutte':'Seleziona tutte'}</button><button class="w-primary" data-action="compose-research" ${chosen.length<1||chosen.length>12?'disabled':''}>Crea ricerca unica</button><button data-action="remove-selected" ${!chosen.length?'disabled':''}>Rimuovi selezionate</button></div><div class="w-cardlist">${state.shelf.map((r,i)=>{const active=selected().includes(r.library_id);return `<article class="w-shelf-card"><label class="w-shelf-choice"><input type="checkbox" data-shelf-check="${i}" aria-label="Seleziona ${esc(r.title)}" ${state.shelfSelection.includes(shelfKey(r))?'checked':''} ${active?'':'disabled'}></label><button class="w-result" data-resume="${i}"><span><strong>${esc(r.title)}</strong><small>${esc(names([r.library_id]))} · Riprendi da pagina ${r.page+1}</small>${active?'':`<small>${library(r.library_id)?.removed?'Ripristina questa libreria dal cestino in Librerie.':'Attiva questa libreria nella barra laterale per includerla nella ricerca.'}</small>`}</span><span aria-hidden="true">↗</span></button><button class="w-shelf-remove" data-remove-shelf="${i}" aria-label="Rimuovi ${esc(r.title)} dallo scaffale">Rimuovi</button></article>`;}).join('')}</div>`:'<p class="w-empty">Apri una voce e scegli “Salva nello scaffale”. Qui ritroverai anche il punto in cui hai interrotto la lettura.</p>'}<section class="w-research-saved"><h2>Ricerche riunite</h2>${state.researches.length?`<div class="w-cardlist">${state.researches.map((r,i)=>`<article class="w-shelf-card"><button class="w-result" data-open-research="${i}"><span><strong>${esc(r.title)}</strong><small>${r.documents.length} voci · ${esc(depthOptions[r.depth]||'Essenziale')} · Ricerca salvata</small></span><span aria-hidden="true">↗</span></button><button data-remove-research="${i}" aria-label="Rimuovi la ricerca ${esc(r.title)}">Rimuovi</button></article>`).join('')}</div>`:'<p class="w-small">Le ricerche che salvi compariranno qui, separate dalle singole voci.</p>'}</section></section>`;
  }
  async function removeShelf(items){const result=await api('shelf/remove',{items});state.removal=result.removed?result:null;await refreshShelf();if(state.view==='shelf')render();}
  async function undoShelf(){if(!state.removal)return;await api('shelf/restore',{token:state.removal.undo});state.removal=null;await refreshShelf();if(state.view==='shelf')render();}
  async function composeResearch(saved=null){
    cancelLiveSearch();const generation=++state.generation;message('Riunisco le voci e verifico i passaggi e le fonti…');
    const data=saved?await api('research/open',{id:saved.id,...scope()}):await api('research',{documents:chosenShelf().map(r=>({library_id:r.library_id,article_id:r.article_id})),...scope()});
    if(generation!==state.generation)return;resetKeywords();state.research=data;state.document=null;state.researchPage=0;state.researchNote=null;state.researchView='reading';state.view='research';render();message('');root.querySelector('.w-main').scrollIntoView({block:'start'});
  }
  let flashTimer=null;
  function keywordRanges(text,term){
    const normalize=x=>x.normalize('NFD').replace(/\p{M}/gu,'').toLocaleLowerCase('it');let flat='',offsets=[],offset=0;
    for(const ch of text){const folded=normalize(ch);for(let j=0;j<folded.length;j++)offsets.push([offset,offset+ch.length]);flat+=folded;offset+=ch.length;}
    const needle=normalize(term),ranges=[];if(!needle)return ranges;
    let pos=0;
    while((pos=flat.indexOf(needle,pos))!==-1){const end=pos+needle.length;const word=c=>c&&/[\p{L}\p{N}_]/u.test(c);if(!word(flat[pos-1])&&!word(flat[end]))ranges.push([offsets[pos][0],offsets[end-1][1]]);pos=end;}
    return ranges;
  }
  function highlighted(text){
    if(!state.flash)return esc(text);const ranges=keywordRanges(text,state.flash.term);let output='',last=0;
    for(const [a,b] of ranges){output+=esc(text.slice(last,a))+`<mark class="w-keyword-flash">${esc(text.slice(a,b))}</mark>`;last=b;}
    return output+esc(text.slice(last));
  }
  function beginFlash(term,doc){
    clearTimeout(flashTimer);state.flash={term,doc};const current=state.flash;
    flashTimer=setTimeout(()=>{if(state.flash!==current)return;state.flash=null;content.querySelectorAll('mark.w-keyword-flash').forEach(e=>e.replaceWith(document.createTextNode(e.textContent)));content.querySelectorAll('.w-keyword-flash').forEach(e=>e.classList.remove('w-keyword-flash'));},3200);
  }
  function focusKeyword(index){
    const d=state.research,doc=d.documents[index];if(!doc||state.researchBusy)return;
    beginFlash(doc.title,index);
    if(state.researchView==='map'){renderResearch();content.querySelector(`[data-map-branch="${index}"] .w-map-keyword`).scrollIntoView({block:'center',behavior:'smooth'});return;}
    const own=d.notes.filter(n=>n.library_id===doc.library_id&&n.article_id===doc.article_id),note=own.find(n=>keywordRanges(n.excerpt,doc.title).length)||d.notes.find(n=>keywordRanges(n.excerpt,doc.title).length)||own[0];
    if(!note){renderResearch();message('Questa voce non contribuisce ai passaggi selezionati. Puoi aprire l’originale con ↗.');return;}
    state.researchPage=d.pages.findIndex(p=>p.some(b=>b.sentences.some(s=>s.note===note.number)));state.researchNote=null;renderResearch();
    const mark=content.querySelector('.w-research-copy mark.w-keyword-flash'),cite=content.querySelector(`[data-research-note="${note.number}"]`);
    const target=mark||cite?.closest('p');if(target){if(!mark)target.classList.add('w-keyword-flash');target.scrollIntoView({block:'center',behavior:'smooth'});}
    message(mark?'':`Passaggio dalla voce «${doc.title}»: il titolo non compare letteralmente nel testo selezionato.`);
  }

  const depthOptions={essential:'Essenziale',extended:'Estesa',deep:'Approfondita'};
  function depthSelect(value,id,disabled=false){return `<select id="${id}" aria-label="Ampiezza della ricerca" ${disabled?'disabled':''}>${Object.entries(depthOptions).map(([k,v])=>`<option value="${k}" ${value===k?'selected':''}>${v}</option>`).join('')}</select>`;}
  function researchHeader(d){return `<div class="w-breadcrumb">Ricerca enciclopedica · ${d.documents.length} voci</div><h1 class="w-research-title">${esc(d.title)}</h1><p class="w-deck">${esc(d.depth_label||'Essenziale')} · ${d.pages.length} ${d.pages.length===1?'pagina':'pagine'} · ${d.notes.length} passaggi con fonte</p><div class="w-research-toolbar"><div class="w-view-switch" aria-label="Vista della ricerca"><button data-action="research-reading" aria-pressed="${state.researchView!=='map'}">Testo</button><button data-action="research-map" aria-pressed="${state.researchView==='map'}">Mappa mentale</button><button data-action="timeline" ${state.researchBusy?'disabled':''}>Linea del tempo</button></div><label class="w-depth-control">Ampiezza ${depthSelect(d.depth||'essential','w-research-depth',state.researchBusy)}</label></div><div class="w-actions"><button data-nav="shelf">Il mio scaffale</button><button data-action="save-research" ${d.saved_id||state.researchBusy?'disabled':''}>${d.saved_id?'✓ Ricerca salvata':'Salva ricerca'}</button><button data-action="export-research" ${state.researchBusy?'disabled':''}>Esporta e stampa</button><button data-nav="settings">Preferenze di lettura</button></div>${keywordEditor(d)}`;}
  function pagination(d,p){return `<nav class="w-bottom" aria-label="Pagine della ricerca"><button data-research-page="${p-1}" ${p===0?'disabled':''}>← Precedente</button><label>Pagina <input type="number" id="w-research-page" aria-label="Pagina della ricerca" min="1" max="${d.pages.length}" value="${p+1}"> di ${d.pages.length}</label><button data-research-page="${p+1}" ${p===d.pages.length-1?'disabled':''}>Successiva →</button></nav>`;}
  function mindMap(d){
    return `<section class="w-mindmap" aria-label="Mappa mentale della ricerca"><div class="w-map-intro"><h2>La ricerca a colpo d’occhio</h2><p class="w-small">Dalle parole chiave ai temi presenti nel testo. Scegli un tema per raggiungere il passaggio e la sua fonte. Le linee organizzano la lettura: non indicano rapporti causali.</p></div><div class="w-map-root">La tua ricerca<span>${d.documents.length} parole chiave · ${d.toc.length} sezioni</span></div><div class="w-map-branches">${d.documents.map((doc,i)=>{
      const entries=d.toc.map(t=>{const nums=[];for(const page of d.pages)for(const b of page)if(b.heading===t.heading)for(const s of b.sentences){const n=d.notes[s.note-1];if(n.library_id===doc.library_id&&n.article_id===doc.article_id)nums.push(n.number);}return {...t,nums};}).filter(t=>t.nums.length);
      return `<section class="w-map-branch" data-map-branch="${i}"><div class="w-map-keyword ${state.flash?.doc===i?'w-keyword-flash':''}"><span class="w-label">Parola chiave ${i+1}</span><h3><button class="w-map-title" data-focus-keyword="${i}">${esc(doc.title)}</button></h3><small>${esc(doc.library_name)}</small><button data-research-original="${i}" aria-label="Apri la voce originale ${esc(doc.title)}">Voce originale ↗</button></div><ul>${entries.map(t=>`<li><button data-map-note="${t.nums[0]}"><strong>${esc(t.heading.replace(doc.title+' — ',''))}</strong><small>${t.nums.length} ${t.nums.length===1?'passaggio':'passaggi'} con fonte · Vai al testo →</small></button></li>`).join('')||'<li class="w-small w-map-empty">Nessun passaggio di questa voce è stato incluso nella selezione attuale. Puoi aumentare l’ampiezza o aprire l’originale.</li>'}</ul></section>`;}).join('')}</div></section>`;
  }
  function renderResearch(){
    const d=state.research;if(!d)return;shell();const p=Math.max(0,Math.min(state.researchPage,d.pages.length-1));state.researchPage=p;const blocks=d.pages[p],n=state.researchNote?d.notes[state.researchNote-1]:null;
    if(state.researchView==='map'){content.innerHTML=`<article class="w-page">${researchHeader(d)}${mindMap(d)}</article>`;keywordResults();return;}
    content.innerHTML=`<article class="w-page">${researchHeader(d)}<details class="w-research-method"><summary>Fonti e copertura · ${d.themes?.length?d.themes.length+' temi condivisi':d.connections.length?d.connections.length+' richiami tra le voci':'Lettura delle voci selezionate'}</summary><p class="w-small">${esc(d.method)}</p><p class="w-small">${esc(d.coverage?.note||'')} Selezionati ${d.selected} passaggi, su ${d.examined.reduce((a,b)=>a+b,0)} esaminati e ${d.available.reduce((a,b)=>a+b,0)} disponibili nelle voci.</p>${d.unconnected?.length?`<p>Voci senza temi condivisi sufficienti: ${d.unconnected.map(esc).join(', ')}. Le voci originali sono accessibili dalle parole chiave.</p>`:''}</details><nav class="w-toc" aria-label="Indice della ricerca"><details><summary>Indice della ricerca · ${d.toc.length} sezioni</summary><div>${d.toc.map(t=>`<button data-research-page="${t.page}">${esc(t.heading)}</button>`).join('')}</div></details></nav><div class="w-reading-position">Pagina ${p+1} di ${d.pages.length} · ${esc(d.depth_label||'Essenziale')}${d.depth==='essential'?' · Per approfondire, scegli Estesa o Approfondita in alto.':''}</div>${p===0&&d.overview?`<p class="w-deck">${esc(d.overview)}</p>`:''}<div class="w-copy w-research-copy" data-columns="${state.prefs.columns?2:1}">${blocks.map((b,i)=>`<section>${i===0||blocks[i-1].heading!==b.heading?`<h3>${esc(b.heading)}</h3>`:''}<p>${b.sentences.map(s=>`${highlighted(s.text)}<button class="w-cite" data-research-note="${s.note}" aria-label="Apri fonte della ricerca ${s.note}">[${s.note}]</button> `).join('')}</p></section>`).join('')}</div>${n?`<aside class="w-source" tabindex="-1" aria-label="Fonte della ricerca"><div class="w-sourcehead"><div><span class="w-label">Fonte [${n.number}] · ${esc(n.title)}</span><h3>${esc(n.library_name)} · ${esc(n.heading)}</h3></div><button data-action="close-research-note" aria-label="Chiudi fonte">×</button></div><blockquote>${esc(n.excerpt)}</blockquote><small>${esc(n.source)}${n.revision?' · Revisione '+esc(n.revision):''}</small><details><summary>Leggi il contesto originale</summary><p>${esc(n.context)}</p></details></aside>`:''}${pagination(d,p)}</article>`;
    keywordResults();
  }
  let keywordTimer=null,keywordGeneration=0;
  function resetKeywords(){clearTimeout(flashTimer);state.flash=null;clearTimeout(keywordTimer);++keywordGeneration;state.keywordQuery='';root.querySelector('#w-search').value='';state.keywordRows=[];state.keywordStatus='';state.researchBusy=false;}
  function keywordEditor(d){return `<section class="w-keywords" aria-label="Parole chiave della ricerca"><div class="w-keyword-heading"><strong>Parole chiave della ricerca</strong><span class="w-small">${d.documents.length}/12 · Il testo si aggiorna quando aggiungi o rimuovi una voce</span></div><div class="w-keyword-chips">${d.documents.map((r,i)=>`<span class="w-keyword-chip"><button data-focus-keyword="${i}" class="${state.flash?.doc===i?'w-keyword-flash':''}" title="Evidenzia nella ricerca">${esc(r.title)}</button><button data-research-original="${i}" aria-label="Apri la voce originale ${esc(r.title)}" title="Apri la voce originale">↗</button><button data-keyword-remove="${i}" aria-label="Rimuovi ${esc(r.title)} dalla ricerca" title="${d.documents.length===1?'Mantieni almeno una parola chiave':'Rimuovi dalla ricerca'}" ${state.researchBusy||d.documents.length===1?'disabled':''}>×</button></span>`).join('')}</div><p id="w-keyword-help" class="w-small">Clicca una parola per evidenziarla; ↗ apre l’originale. Usa la barra in alto per aggiungere argomenti e × per rimuoverli. Da 1 a 12 voci delle librerie attive. ${d.saved_id?'Le modifiche creano una nuova ricerca: quella salvata resta nello scaffale.':''}</p><div id="w-keyword-results" aria-live="polite"></div></section>`;}
  function keywordResults(){
    const area=content.querySelector('#w-keyword-results');if(!area)return;
    area.innerHTML=`<p class="w-small">${esc(state.keywordStatus||'')}</p>${(state.keywordRows||[]).map((r,i)=>{const exists=state.research.documents.some(x=>shelfKey(x)===shelfKey(r));return `<button class="w-keyword-result" data-keyword-add="${i}" ${exists||state.researchBusy?'disabled':''}><span><strong>${esc(r.title)}</strong><small>${esc(r.library_name||names([r.library_id]))}${r.similar?' · Titolo simile':''}</small></span><span>${exists?'Già inclusa':'＋ Aggiungi'}</span></button>`;}).join('')}`;
  }
  async function findKeyword(){
    clearTimeout(keywordTimer);const query=state.keywordQuery.trim(),d=state.research,generation=state.generation,kg=++keywordGeneration;
    if(state.view!=='research'||state.researchBusy)return;
    if(query.length<2){state.keywordRows=[];state.keywordStatus='Scrivi almeno due caratteri.';keywordResults();return;}
    state.keywordRows=[];state.keywordStatus='Cerco nelle librerie selezionate…';keywordResults();
    try{const result=await api('search',{query,...scope(),limit:8});
      if(kg!==keywordGeneration||generation!==state.generation||state.view!=='research'||d!==state.research)return;
      const seen=new Set();state.keywordRows=[...result.rows,...(result.suggestions||[]).map(r=>({...r,similar:true}))].filter(r=>{const key=shelfKey(r);if(seen.has(key))return false;seen.add(key);return true;}).slice(0,12);
      state.keywordStatus=state.keywordRows.length?'Scegli la voce da aggiungere'+(result.next?' · Precisa il titolo per restringere i risultati.':'.'):'Nessuna voce trovata nelle librerie attive. Prova un altro nome.';keywordResults();
    }catch(e){if(kg!==keywordGeneration||generation!==state.generation||state.view!=='research')return;state.keywordStatus=e.message;keywordResults();}
  }
  async function changeKeywords(refs,depth=state.research.depth){
    if(state.researchBusy||!refs.length||refs.length>12)return;
    const old=state.research,generation=++state.generation;clearTimeout(keywordTimer);++keywordGeneration;state.researchBusy=true;state.keywordRows=[];state.keywordStatus='Aggiornamento della ricerca…';renderResearch();message('Aggiorno le pagine e verifico le fonti…');
    try{const data=await api('research',{documents:refs,depth,...scope()});
      if(generation!==state.generation||state.view!=='research'||state.research!==old)return;
      state.research=data;state.researchPage=0;state.researchNote=null;resetKeywords();renderResearch();message('Ricerca aggiornata: '+data.documents.length+' '+(data.documents.length===1?'parola chiave':'parole chiave')+' · '+data.pages.length+' '+(data.pages.length===1?'pagina':'pagine')+'.');
    }catch(e){if(generation===state.generation&&state.view==='research'){state.keywordStatus='Aggiornamento non riuscito. La ricerca precedente è conservata.';message(e.message,true);}}
    finally{if(generation===state.generation&&state.view==='research'){state.researchBusy=false;renderResearch();}else if(state.research===old)state.researchBusy=false;}
  }
  async function extendArticle(){
    const ref=reference(state.document),generation=++state.generation;message('Preparo la ricerca…');const data=await api('research',{documents:[ref],...scope()});if(generation!==state.generation)return;
    resetKeywords();state.research=data;state.document=null;state.researchPage=0;state.researchNote=null;state.researchView='reading';state.view='research';render();message('');root.querySelector('#w-search').value='';root.querySelector('#w-search').focus();
  }
  function turnResearch(p){if(!Number.isInteger(p)||!state.research)return;state.researchView='reading';state.researchPage=Math.max(0,Math.min(p,state.research.pages.length-1));state.researchNote=null;renderResearch();root.querySelector('.w-main').scrollIntoView({block:'start'});}
  const researchRefs=()=>state.research.documents.map(reference);
  async function saveResearch(){const d=state.research;const result=await api('research/save',{documents:researchRefs(),depth:d.depth,...scope()});if(d===state.research){d.saved_id=result.id;renderResearch();message('Ricerca salvata nello scaffale.');}}
  async function exportResearch(){const result=await api('research/export',{documents:researchRefs(),depth:state.research.depth,...scope()});const a=document.createElement('a');a.href=result.url;a.download='Ricerca Wiki22.html';document.body.appendChild(a);a.click();a.remove();feedback.innerHTML='Ricerca pronta. <a href="'+esc(result.url)+'" download>Scarica il documento con le fonti</a>';}

  function renderAbout(){
    const technologies=[
      ['22CK · KC001','Tecnologia 22','Contenitore di conoscenza con dizionario di token, blocchi compressi, indici e controlli di integrità.','Importare documenti, cercare voci e aprire passaggi senza caricare tutta la biblioteca in memoria.'],
      ['INGEST001 e importazione documentale','Tecnologia 22 + convertitori','Estrazione, normalizzazione e costruzione delle librerie; il nuovo importatore conserva anche il testo leggibile verificato.','Trasformare file e cartelle supportati in 22CK, mantenendo gli originali e un rapporto per file.'],
      ['READ001 e provenienza','Tecnologia 22','Lettura documentaria collegata alle evidenze locali, con riferimenti e contesto.','Leggere pagine enciclopediche, aprire le citazioni ed esportare la lettura. Per Wikipedia sono passaggi disponibili, non sempre l’articolo integrale.'],
      ['Gestione delle librerie','Componente Wiki22','Registro delle raccolte e ricerca su una selezione esplicita di fonti.','Consultare una libreria, un gruppo scelto o tutte insieme; mantenere separate le raccolte originali.'],
      ['Confronto e linea del tempo','Componente Wiki22','Allineamento testuale e riconoscimento di date esplicite.','Vedere differenze e passaggi comuni con entrambe le fonti; ordinare le date citate. Uguaglianza del testo non significa accordo semantico.'],
      ['MEMIDX · LOCO','Tecnologia 22','Indici derivati di entità e collegamenti, con rilettura delle evidenze.','Componenti del motore conservati. La precedente sezione Collegamenti è stata rimossa dalla navigazione; Esplora propone ora percorsi per categorie.'],
      ['MEM · LANG001','Tecnologia 22','Diario persistente di osservazioni e formazione di ipotesi lessicali delimitate.','Osservare le letture manualmente o in automatico, ritrovarne la provenienza e vedere le metriche. Lo scaffale salva segnalibri; la memoria registra osservazioni.'],
      ['Ragionamento nativo · Reflection','Tecnologia AI22','Regole esplicite, verifica delle premesse e controllo dei passaggi della risposta.','Interrogare una voce nelle forme supportate, con fonti e motivazione; dichiarare quando le prove non bastano.'],
      ['SELF001 · CAP001 · STATE001','Tecnologia 22','Ispezione del codice, prove tecniche autorizzate e legame tra ricevute e versione verificata.','Eseguire la diagnosi e distinguere capacità provate, componenti rilevati e limiti. Non misura QI umano o certificazioni linguistiche.'],
      ['GTK 3 · WebKitGTK','Stack esterno','Finestra Linux dedicata e motore per visualizzare le pagine locali.','Aprire la finestra dedicata nell’installazione Linux locale. L’edizione da condividere usa il browser già presente sul computer.'],
      ['Python 3 · libreria standard','Stack esterno','Servizio locale, estrazione dei documenti e coordinamento delle funzioni.','Usare Wiki22 sul proprio computer nella finestra dedicata o nel browser.'],
      ['HTML · CSS · JavaScript','Stack esterno','Interfaccia web locale, navigazione e impaginazione.','Leggere a una o due colonne, regolare il testo e consultare fonti, confronti e mappe.'],
      ['SQLite · zlib · SHA-256','Stack esterno','Archivi locali, compressione standard e impronte di integrità.','Conservare preferenze, scaffale e memoria; comprimere blocchi e rilevare modifiche ai dati verificati. Sono componenti riutilizzati, non invenzioni di 22.'],
      ['Poppler / pypdf','Convertitore esterno','Estrazione locale del testo dai PDF; pypdf è incluso nell’edizione da condividere.','Importare PDF con testo. Per scansioni serve OCR esterno; i formati Kindle richiedono Calibre, attualmente non incluso.']
    ];
    content.innerHTML=`<article class="w-page w-about">
      <div class="w-breadcrumb">Dentro 22 · Il progetto</div>
      <div class="w-about-intro"><span class="w-about-number" aria-hidden="true">22</span><div><h1>La conoscenza,<br>vicina a te.</h1><p class="w-deck">Una biblioteca personale da leggere, confrontare e attraversare. Con le fonti sempre a portata di mano.</p></div></div>
      <section class="w-about-section"><h2>Chi siamo, che cosa costruiamo</h2><p>22 è il progetto tecnologico che prende forma in AI22 e Wiki22: strumenti per organizzare la conoscenza locale, seguirne i collegamenti e rendere verificabili le operazioni sui testi. <strong>Wiki22 ne è l’esperienza enciclopedica</strong>: un luogo per la cultura, lo studio e la ricerca nelle proprie raccolte.</p><p>Il punto di partenza è la tua biblioteca. Puoi aggiungere documenti, scegliere quali librerie consultare e tornare dal testo alla fonte. Le raccolte rimangono distinte anche quando le esplori insieme.</p></section>
      <section class="w-about-section w-about-principle"><h2>Funziona senza LLM</h2><p>La consultazione di Wiki22 non richiede un modello linguistico generativo, un servizio AI remoto o una chiave API. Lettura, ricerca, collegamenti e ragionamento nativo lavorano localmente con indici, regole esplicite e passaggi documentati.</p><p>Le pagine mostrano contenuti dalle fonti; le risposte verificate usano le prove disponibili. La comprensione libera di qualsiasi domanda non è una capacità acquisita: quando una forma o una prova non sono supportate, il motore lo dichiara.</p><div class="w-about-pills"><span>Locale</span><span>Fonti consultabili</span><span>0 chiamate LLM nel funzionamento principale</span></div></section>
      <section class="w-about-section"><h2>22CK: conoscenza compatta e consultabile</h2><p>Il formato <strong>22CK V3</strong> organizza articoli, passaggi, riferimenti e indici in un contenitore compatto. Dizionari di token e pagine compresse permettono di leggere le parti necessarie. Le impronte di integrità verificano che il contenuto consultato corrisponda a quello registrato.</p><p>Durante l’importazione, i documenti supportati vengono convertiti in 22CK. Un indice documentale associato conserva la grafia del testo estratto e la verifica contro i token del contenitore. Gli originali restano al loro posto.</p>
      <div class="w-about-compression"><div><span class="w-small">MISURA SU UNA PARTIZIONE WIKIPEDIA</span><strong>52,7% di spazio in meno</strong><p>0,959 GB di testo canonico → 0,453 GB di 22CK, <strong class="w-inline">indici inclusi</strong>.</p><div class="w-about-bar w-about-before"><span>Testo in ingresso · 958.570.043 byte</span></div><div class="w-about-bar w-about-after"><span>22CK · 453.478.941 byte</span></div><p class="w-small">123.900 voci · rapporto di circa 2,11:1. Misura del progetto sulla partizione 1; il risultato varia con contenuto e dimensione della raccolta.</p></div></div>
      <div class="w-about-facts"><div><strong>1.984.914</strong><span>Voci nel corpus Wikipedia italiano verificato</span></div><div><strong>13.936.939</strong><span>Passaggi di evidenza</span></div><div><strong>5,12 GB</strong><span>Contenitori 22CK del corpus completo, con indici interni</span></div></div>
      <details class="w-about-details"><summary>Come leggere questi numeri</summary><p>I valori del corpus si riferiscono allo snapshot Wikimedia <strong>20260901</strong>, verificato su 10 partizioni. Sono misure di quella raccolta, non il conteggio aggiornato delle librerie personali. GB indica miliardi di byte.</p><p>I 5.122.548.547 byte dei contenitori non includono l’applicazione, la memoria personale o gli indici aggiuntivi di lettura e navigazione. Il dump XML espanso di partenza misurava 18,45 GB: la riduzione di ingombro è circa il 72,2%, ma comprende selezione ed elaborazione del contenuto e non è una compressione reversibile dell’intero XML. Il dump originale già compresso in BZ2 misurava 4,25 GB; quel file non offre gli stessi indici di consultazione del 22CK.</p><p>Il formato conserva la rappresentazione canonica verificata. Non promette di ricostruire tutti i byte, le immagini o l’impaginazione del documento originale. Anche un file piccolo può crescere a causa degli indici.</p><p class="w-small">Fonti delle misure nel progetto: <code>evidence/compact_runtime_v3/FINAL_MASTER_HANDOFF.json</code> e <code>evidence/wikipedia_it_ingest001/FULL_WIKIPEDIA_IT_22CK_GATE.json</code>.</p></details></section>
      <section class="w-about-section"><h2>Le tecnologie, e ciò che ti permettono di fare</h2><p>Il progetto combina tecnologie 22 e componenti software esistenti. Questa tabella distingue il loro ruolo nell’enciclopedia installata.</p><div class="w-about-table-wrap" role="region" aria-label="Tabella delle tecnologie, scorrimento orizzontale" tabindex="0"><table class="w-about-table"><caption>Tecnologie della versione locale di Wiki22</caption><thead><tr><th scope="col">Tecnologia</th><th scope="col">Origine</th><th scope="col">Che cosa fa</th><th scope="col">Che cosa puoi fare</th></tr></thead><tbody>${technologies.map(row=>`<tr>${row.map((v,i)=>i===0?`<th scope="row">${esc(v)}</th>`:`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>
      <section class="w-about-section"><h2>Un progetto che si può verificare</h2><p>La baseline locale 056 è stata collaudata con <strong>818 test software</strong>. Le sei prove tecniche SELF001/CAP001 hanno dato esito <strong>6/6</strong>. Sono risultati della versione verificata: puoi eseguire nuovamente la diagnosi dalla relativa sezione.</p><p>Nuove osservazioni e nuove parole non equivalgono automaticamente a maggiore comprensione. Per questo Wiki22 distingue memoria, ipotesi e capacità provate, senza assegnarsi un QI umano o un livello linguistico certificato.</p><div class="w-actions"><button data-nav="libraries">Aggiungi conoscenza</button><button data-nav="memory">Esplora la memoria</button><button data-nav="diagnosis">Apri la diagnosi</button></div><p class="w-small">Wiki22 1.10 · Anteprima di sviluppo · Enciclopedia, mappe e ricerca estesa · Funzioni enciclopediche dalla baseline 056 · Nessun servizio AI esterno richiesto.</p></section>
    </article>`;
  }

  async function bootstrap(){const data=await api('bootstrap');state.libraries=data.libraries;state.prefs=data.preferences;state.shelf=data.shelf;render();}
  async function savePrefs(){await api('preferences',state.prefs);}
  async function search(query,more=false,explore=false){
    cancelLiveSearch();state.suggestions=[];
    const generation=++state.generation;state.view='search';state.query=query.trim();state.document=null;state.note=null;state.comparison=null;state.timeline=null;shell();
    if(!selected().length){state.rows=[];state.next=null;render();message('Seleziona almeno una libreria.',true);return;}
    if(!more)content.innerHTML='<div class="w-page"><h2>Sto cercando nelle tue librerie…</h2></div>';
    message('');try{const result=await api('search',{query:state.query,...scope(),after:more?state.next:null});if(generation!==state.generation)return;state.rows=more?[...state.rows,...result.rows]:result.rows;state.next=result.next;state.suggestions=result.suggestions||[];render();}catch(e){if(generation!==state.generation)return;state.rows=[];state.next=null;render();message(e.message,true);}
  }
  async function openArticle(row,page=0){
    cancelLiveSearch();
    const generation=++state.generation;state.view='article';state.document=null;state.note=null;state.comparison=null;state.timeline=null;shell();content.innerHTML='<div class="w-page"><h2>Apertura della voce…</h2><p class="w-small">Controllo il testo e le fonti locali.</p></div>';message('');
    try{const result=await api('article',{library_id:row.library_id,article_id:row.article_id,...scope()});if(generation!==state.generation)return;state.document=result;state.page=page;render();document.title=result.title+' — Wiki22';if(state.prefs.automatic_learning)observeDocument(true).catch(e=>message('Osservazione non eseguita: '+e.message,true));}catch(e){if(generation!==state.generation)return;state.view='home';render();message(e.message,true);}
  }
  async function saveComfort(values,focusId){
    if(state.comfortBusy)return;state.comfortBusy=true;const old={...state.prefs},view=state.view;
    content.querySelectorAll('.w-setting input,.w-setting select,.w-palette input,[data-action="reset-comfort"]').forEach(e=>e.disabled=true);
    try{state.prefs=await api('preferences',values);if(state.view===view)message('Preferenze di lettura salvate.');}
    catch(err){state.prefs=old;message('Non è stato possibile salvare: '+err.message,true);}
    finally{state.comfortBusy=false;shell();if(state.view==='settings'){settings();if(focusId)content.querySelector('#'+focusId)?.focus();}}
  }
  async function navigate(view){cancelLiveSearch();++state.generation;state.view=view;message('');clearTimeout(catalogTimer);if(view==='catalog'){render();await refreshCatalog();return;}if(view==='places'){root.querySelector('#w-search').value=state.placeQuery||'';}if(view==='timeline'){if(!state.timeline)return calendarStart('home');state.timelineBusy=false;render();root.querySelector('.w-main').scrollIntoView({block:'start'});return;}if(view==='explore'){state.explorePath=null;state.exploreCategory='all';root.querySelector('#w-search').value='';const generation=state.generation;message('Preparo i percorsi…');const categories=await api('explore');if(generation!==state.generation)return;state.categories=categories;render();message('');root.querySelector('.w-main').scrollIntoView({block:'start'});return;}if(view==='graph')return showGraph();if(view==='memory')return showMemory();if(view==='shelf')await refreshShelf();render();root.querySelector('.w-main').scrollIntoView({block:'start'});}
  async function scopeChanged(){cancelLiveSearch();state.shelfSelection=[];state.research=null;const current=state.document,page=state.page;const generation=++state.generation;state.document=null;state.note=null;state.comparison=null;state.timeline=null;state.graph=null;state.reason=null;state.places=null;state.placeRows=[];state.placeQuery='';state.view='home';render();await savePrefs();if(generation===state.generation&&current&&selected().includes(current.library_id))await openArticle(current,page);}
  async function bookmark(saved=undefined){const d=state.document;if(!d)return;const next=saved??!d.saved;await api('bookmark',{library_id:d.library_id,article_id:d.article_id,...scope(),source_hash:d.source_hash,page:state.page,saved:next});if(state.document===d){d.saved=next;state.shelf=await api('shelf');if(state.view==='article')renderArticle();}}
  async function turn(page){if(!state.document||!Number.isInteger(page))return;state.page=Math.max(0,Math.min(page,state.document.pages.length-1));state.note=null;renderArticle();if(state.document.saved)await bookmark(true);}
  async function poll(job){for(;;){const result=await api('job',{job});if(result.status==='DONE')return result.result;await new Promise(resolve=>setTimeout(resolve,500));}}
  async function pick(kind){message('Scegli il file o la cartella nella finestra del computer.');const result=await poll((await api('pick',{kind})).job);if(result.path&&state.view==='libraries'){root.querySelector('#w-import-path').value=result.path;const name=root.querySelector('#w-import-name');if(!name.value)name.value=result.path.split(/[\\/]/).filter(Boolean).pop().replace(/\.[^.]+$/,'');}message('');}
  async function importLibrary(){const path=root.querySelector('#w-import-path').value.trim(),name=root.querySelector('#w-import-name').value.trim();if(!path||!name){message('Scegli il percorso e assegna un nome alla libreria.',true);return;}state.importing=true;const button=root.querySelector('[data-action="import"]');button.disabled=true;message('Importazione in corso. I file originali restano invariati.');try{const result=await poll((await api('import',{path,name})).job);const data=await api('bootstrap');state.libraries=data.libraries;state.importing=false;state.importReport=result;render();message(result.id?'Libreria «'+result.name+'» convertita in 22CK: '+countLabel(result.articles)+'. Consulta il rapporto.':'Nessun file importato. Consulta il rapporto.',!result.id);}finally{state.importing=false;const b=root.querySelector('[data-action="import"]');if(b)b.disabled=false;}}
  async function exportDocument(){const d=state.document;if(!d)return;message('Preparazione delle pagine e delle fonti…');const result=await api('export',{library_id:d.library_id,article_id:d.article_id,...scope(),expected:d.source_hash});const a=document.createElement('a');a.href=result.url;a.download=d.title.replace(/[^\p{L}\p{N} _-]/gu,'_')+' — Wiki22.html';document.body.appendChild(a);a.click();a.remove();message('Esportazione pronta.');feedback.innerHTML='<strong>Esportazione pronta.</strong> <a href="'+esc(result.url)+'" download>Scarica il documento</a><details><summary>Dove trovo la copia sul PC?</summary><span>'+esc(result.path)+'</span></details>';}

  const reference=d=>({library_id:d.library_id,article_id:d.article_id,source_hash:d.source_hash});
  function sourceDetails(note,d){if(!note)return '';return `<details class="w-proof"><summary>${esc(d.library_name)} · fonte [${note.number}]</summary><p>${esc(note.heading)}${note.revision?' · Revisione '+esc(note.revision):''}</p><p class="w-note-context">${esc(note.context)}</p><small>${esc(note.source)}</small>${note.revision_url?.startsWith('https://it.wikipedia.org/')?`<p><a href="${esc(note.revision_url)}" target="_blank" rel="noreferrer noopener">Originale online ↗</a></p>`:''}</details>`;}
  function renderCompare(){
    const c=state.comparison;
    if(!c){content.innerHTML=`<section class="w-page"><div class="w-breadcrumb">Confronta le fonti</div><h1>${esc(state.document.title)}</h1><p>Voce di partenza: ${esc(state.document.library_name)}. Scegli una voce da un’altra libreria selezionata. Il titolo può essere diverso.</p><div class="w-row"><input id="w-compare-query" aria-label="Titolo da confrontare" maxlength="180" value="${esc(state.compareQuery)}"><button data-action="find-comparison">Cerca nell’altra libreria</button><button data-action="back-reading">← Lettura</button></div>${selected().length<2?'<p>Seleziona almeno due librerie nella barra laterale per confrontarle.</p>':''}<div class="w-cardlist">${state.compareChoices.map((r,i)=>`<button class="w-result" data-comparison="${i}"><span><strong>${esc(r.title)}</strong><small>${esc(r.library_name)}</small></span></button>`).join('')}</div>${state.compareSearched&&!state.compareChoices.length?'<p>Nessuna voce corrispondente nelle altre librerie selezionate. Cerca un altro titolo oppure aggiungi una raccolta alla selezione.</p>':''}</section>`;return;}
    const list=state.commonOnly?c.rows.filter(r=>r.kind==='common'):c.rows;
    const labels={common:'Punto di incontro · testo identico',different:'Passaggi diversi da confrontare',left_only:'Passaggio aggiuntivo A',right_only:'Passaggio aggiuntivo B'};
    const sentence=(n,parts)=>parts?parts.map(p=>p.changed?`<mark>${esc(p.text)}</mark>`:esc(p.text)).join(''):esc(n?.excerpt||'—');
    content.innerHTML=`<section class="w-page"><div class="w-breadcrumb">Confronto tra librerie</div><h1>${esc(c.left.title)}</h1><p><strong>A · ${esc(c.left.library_name)}</strong> — ${esc(c.left.title)}<br><strong>B · ${esc(c.right.library_name)}</strong> — ${esc(c.right.title)}</p><div class="w-actions"><button data-action="back-reading">← Lettura</button><button data-action="choose-comparison">Cambia confronto</button><button data-action="combined" aria-pressed="${state.combined}">${state.combined?'Vista affiancata':'Lettura combinata'}</button><button data-action="common-only" aria-pressed="${state.commonOnly}">Punti di incontro (${c.counts.common})</button><button data-action="timeline">Linea del tempo delle due fonti</button></div><p class="w-small">${esc(c.method)}</p><p>${c.counts.common} ${c.counts.common===1?'punto di incontro':'punti di incontro'} · ${c.counts.different} ${c.counts.different===1?'coppia diversa':'coppie diverse'} · ${c.counts.left_only+c.counts.right_only} passaggi aggiuntivi.</p>${c.limited?'<p class="w-error">Confronto limitato ai primi passaggi disponibili: '+c.examined.join(' / ')+' esaminati su '+c.total.join(' / ')+'.</p>':''}<div class="w-comparisons">${list.map(r=>`<section class="w-comparison ${r.kind==='common'?'w-common':''}"><h3>${labels[r.kind]}</h3>${state.combined&&r.kind==='common'?`<p>${esc(r.left.excerpt)}</p><div class="w-pair">${sourceDetails(r.left,c.left)}${sourceDetails(r.right,c.right)}</div>`:`<div class="w-pair"><div><span class="w-label">A · ${esc(c.left.library_name)}</span><p>${sentence(r.left,r.changes?.[0])}</p>${sourceDetails(r.left,c.left)}</div><div><span class="w-label">B · ${esc(c.right.library_name)}</span><p>${sentence(r.right,r.changes?.[1])}</p>${sourceDetails(r.right,c.right)}</div></div>`}</section>`).join('')||'<p>Non ci sono passaggi testualmente identici nelle due letture disponibili.</p>'}</div></section>`;
  }
  const timelineMonths=['gennaio','febbraio','marzo','aprile','maggio','giugno','luglio','agosto','settembre','ottobre','novembre','dicembre'];
  function dateFields(){
    const f=state.timelineDraft||{},busy=state.timelineBusy?'disabled':'';
    return `<form id="w-date-form" class="w-date-search" aria-label="Ricerca per data"><h2>Esplora una data</h2><p class="w-small">Scegli un anno. Aggiungi il mese e, se vuoi, il giorno per restringere gli eventi.</p><div class="w-date-fields"><label>Anno<input id="w-date-year" type="number" min="1" max="9999" step="1" placeholder="Es. 1969" value="${esc(f.year||'')}" required ${busy}></label><label>Epoca<select id="w-date-era" ${busy}><option value="1" ${f.era!=='-1'?'selected':''}>d.C.</option><option value="-1" ${f.era==='-1'?'selected':''}>a.C.</option></select></label><label>Mese<select id="w-date-month" ${busy}><option value="">Tutto l’anno</option>${timelineMonths.map((m,i)=>`<option value="${i+1}" ${Number(f.month)===i+1?'selected':''}>${m}</option>`).join('')}</select></label><label>Giorno<select id="w-date-day" ${busy||(!f.month?'disabled':'')}><option value="">Tutto il mese</option>${Array.from({length:31},(_,i)=>`<option value="${i+1}" ${Number(f.day)===i+1?'selected':''}>${i+1}</option>`).join('')}</select></label><label class="w-date-scope">Cerca in<select id="w-date-source" ${busy}>${state.timelineRefs?.length?`<option value="current" ${f.source!=='calendar'?'selected':''}>Argomenti aperti</option>`:''}<option value="calendar" ${f.source==='calendar'?'selected':''}>Calendario delle librerie</option></select></label><button type="submit" class="w-primary" ${busy}>${state.timelineBusy?'Ricerca…':'Cerca eventi'}</button><button type="button" data-action="date-reset" ${busy}>Azzera data</button></div><p class="w-small">${f.source==='calendar'?'Consulta le voci annuali e del giorno presenti nelle librerie selezionate.':'Filtra le date citate negli argomenti aperti.'} Un evento senza mese o giorno preciso non compare nei filtri più dettagliati.</p></form>`;
  }
  function readDateDraft(){
    const value=id=>content.querySelector('#w-date-'+id)?.value||'';
    return {year:value('year'),era:value('era'),month:value('month'),day:value('day'),source:value('source')};
  }
  function calendarStart(origin='explore'){
    ++state.generation;state.timelineBusy=false;state.timelineRefs=origin==='home'?(state.research?.documents|| (state.document?[state.document]:[])).map(reference):[];state.timelineOrigin=origin;state.timelineDraft={source:'calendar',era:'1'};
    state.timeline={documents:[],events:[],highlights:[],method:'',selection_method:'',date_filter:{year:null},initial:true};state.timelineMode='horizontal';state.view='timeline';render();message('');content.querySelector('#w-date-year').focus();
  }
  async function findTimelineDate(reset=false){
    if(state.timelineBusy)return;const draft=reset?{source:state.timelineRefs?.length?'current':'calendar',era:'1'}:readDateDraft();state.timelineDraft=draft;
    if(reset&&!state.timelineRefs?.length){calendarStart();return;}
    const values=reset?{}:{year:Number(draft.year)*Number(draft.era),month:draft.month?Number(draft.month):null,day:draft.day?Number(draft.day):null};
    const generation=++state.generation;state.timelineBusy=true;renderTimeline();message('Cerco eventi con la precisione richiesta…');
    try{
      const result=await api(draft.source==='calendar'?'timeline/date':'timeline',draft.source==='calendar'?{...values,...scope()}:{documents:state.timelineRefs,...values,...scope()});
      if(generation!==state.generation)return;state.timeline=result;state.timelineMode=result.highlights.length?'horizontal':'list';
      message(result.events.length?`${result.events.length} ${result.events.length===1?"riferimento datato trovato":"riferimenti datati trovati"}${result.date_filter.year!==null?' per '+result.date_filter.label:''}.`:'Nessuna corrispondenza esatta nelle voci consultate: non significa che quel giorno non siano accaduti eventi.');
    }catch(err){if(generation===state.generation)message(err.message,true);}
    finally{if(generation===state.generation){state.timelineBusy=false;renderTimeline();}}
  }

  function renderTimeline(){
    const t=state.timeline;if(!t)return;const horizontal=state.timelineMode==='horizontal',filtered=t.date_filter?.year!=null;
    if(t.initial){content.innerHTML=`<section class="w-page"><div class="w-breadcrumb">Il contesto nel tempo</div><h1>Linea del tempo</h1><p class="w-deck">Scopri cosa accadeva in un anno, un mese o un giorno.</p><div class="w-actions"><button data-action="timeline-back">← ${state.timelineOrigin==='home'?'Enciclopedia':'Esplora'}</button></div>${dateFields()}</section>`;return;}
    const excerpt=e=>`${esc(e.note.excerpt.slice(e.date.segment?.[0]||0,e.date.offsets[0]))}<mark>${esc(e.note.excerpt.slice(...e.date.offsets))}</mark>${esc(e.note.excerpt.slice(e.date.offsets[1],e.date.segment?.[1]))}`;
    content.innerHTML=`<section class="w-page"><div class="w-breadcrumb">Il contesto nel tempo</div><h1>Linea del tempo</h1><p class="w-deck">${filtered?esc(t.date_filter.label)+' · ':''}${t.documents.map(d=>esc(d.title)).join(' · ')||'Anno, mese e giorno nelle tue fonti'}</p><div class="w-actions"><button data-action="timeline-back">← ${state.timelineOrigin==='home'?'Enciclopedia':state.timelineOrigin==='explore'?'Esplora':state.timelineOrigin==='research'?'Torna alla ricerca':state.timelineOrigin==='compare'?'Torna al confronto':'Torna alla lettura'}</button></div>${dateFields()}${t.initial?'<p class="w-empty">Inserisci un anno per cominciare, per esempio 1969.</p>':''}<div class="w-timeline-controls" aria-label="Vista della cronologia"><button data-timeline-mode="horizontal" aria-pressed="${horizontal}">Panoramica orizzontale · ${t.highlights.length}</button><button data-timeline-mode="list" aria-pressed="${!horizontal}">${filtered?'Tutti i risultati':'Tutte le date'} · ${t.events.length}</button></div><details class="w-timeline-method"><summary>Fonti e criteri della ricerca</summary><p class="w-small">${esc(t.method)}</p></details>${t.limited?'<p class="w-error">Cronologia limitata ai primi passaggi disponibili di ogni voce.</p>':''}${horizontal?`<h2>${filtered?'Eventi in evidenza · '+esc(t.date_filter.label):'Tappe in evidenza'}</h2><p class="w-small">Una selezione automatica per orientarti, con la fonte di ogni passaggio. Scorri da sinistra a destra o usa le frecce.</p><details class="w-timeline-method"><summary>Come sono scelte e disposte le tappe</summary><p class="w-small">${esc(t.selection_method)}</p></details>${t.highlights.length?`<div class="w-time-navigation"><button data-timeline-scroll="-1" aria-label="Scorri verso le date precedenti">← Precedenti</button><span class="w-small">${esc(t.events[t.highlights[0]].date.label)} → ${esc(t.events[t.highlights[t.highlights.length-1]].date.label)}</span><button data-timeline-scroll="1" aria-label="Scorri verso le date successive">Successive →</button></div><div class="w-time-track" role="region" tabindex="0" aria-label="Tappe in ordine cronologico; scorri orizzontalmente"><ol>${t.highlights.map(i=>{const e=t.events[i],d=t.documents[e.document];return `<li class="w-time-stop"><div class="w-time-date">${esc(e.date.label)}</div><article><div class="w-label">${esc(d.title)}</div><h3>${esc(e.note.heading)}</h3><p>${excerpt(e)}</p>${e.date.context_date?`<p class="w-small">${esc(e.date.context_date)}</p>`:''}${sourceDetails(e.note,d)}</article></li>`;}).join('')}</ol></div>`:'<p class="w-empty">Non ci sono tappe da evidenziare. Consulta l’elenco completo o prova un periodo più ampio.</p>'}`:`<div class="w-time-list">${t.events.map(e=>`<article class="w-time-event"><div class="w-time-date">${esc(e.date.label)}${e.bibliographic?'<small class="w-small">Riferimento bibliografico</small>':''}</div><div><span class="w-label">${esc(t.documents[e.document].title)}</span><p>${excerpt(e)}</p>${e.date.context_date?`<p class="w-small">${esc(e.date.context_date)}</p>`:''}${sourceDetails(e.note,t.documents[e.document])}</div></article>`).join('')||'<p class="w-empty">Nessun riferimento con questa precisione nelle fonti consultate. Prova solo l’anno, cambia l’ambito o azzera la data.</p>'}</div>`}</section>`;
    if(filtered&&!t.events.length){content.insertAdjacentHTML('beforeend',`<section class="w-page w-calendar-help"><h2>Una data senza corrispondenze</h2><p>Le voci locali consultate non documentano questa data con la precisione richiesta. La biblioteca non contiene necessariamente tutti gli eventi di ogni giorno.</p><div class="w-row">${t.date_filter.day?'<button data-action="date-month">Esplora lo stesso mese</button>':''}<button data-action="date-year">Esplora tutto l’anno</button></div>${t.nearby?.events.length?`<h3>Nello stesso mese · ${esc(t.nearby.label)}</h3><p class="w-small">Questi eventi hanno date diverse da quella cercata.</p>${t.nearby.events.map(e=>`<article class="w-time-event"><div class="w-time-date">${esc(e.date.label)}</div><div><p>${excerpt(e)}</p>${sourceDetails(e.note,t.documents[e.document])}</div></article>`).join('')}`:''}</section>`);}

  }

  function renderExplore(){
    const categories=state.categories||[],path=state.explorePath;
    content.innerHTML=`<section class="w-page w-explore"><div class="w-breadcrumb">Percorsi nella tua biblioteca</div><h1>Esplora per curiosità.</h1><p class="w-deck">Una domanda da approfondire, più voci da leggere insieme.</p><div class="w-actions"><button data-action="calendar-start">Esplora una data →</button></div><div class="w-category-tabs" aria-label="Categorie"><button data-category="all" aria-pressed="${state.exploreCategory==='all'}">Tutte</button>${categories.map(c=>`<button data-category="${esc(c.id)}" aria-pressed="${state.exploreCategory===c.id}">${esc(c.title)}</button>`).join('')}</div>${path?`<section class="w-path-preview" aria-label="Voci del percorso"><div class="w-breadcrumb">Prepara la tua ricerca</div><h2>${esc(path.path.title)}</h2><p>${esc(path.path.question)}</p><p class="w-small">${esc(path.method)}</p>${path.missing.length?`<p class="w-path-missing">Non disponibili nelle librerie selezionate: ${path.missing.map(esc).join(', ')}. Puoi importare una raccolta o cambiare le librerie.</p>`:''}${path.limited?'<p class="w-small">Sono mostrati i primi risultati per titolo. In caso di molte edizioni, restringi le librerie selezionate.</p>':''}<div class="w-path-sources">${path.rows.map((r,i)=>`<div><label><input type="checkbox" data-path-check="${i}" ${state.pathBusy?'disabled':''} ${state.pathSelection.includes(i)?'checked':''}><span><strong>${esc(r.title)}</strong><small>${esc(r.library_name)}</small></span></label><button data-path-article="${i}" aria-label="Leggi ${esc(r.title)} da ${esc(r.library_name)}">Leggi ↗</button></div>`).join('')||'<p>Nessuna delle voci proposte è presente. La barra in alto può cercare altri argomenti nelle tue raccolte.</p>'}</div><div class="w-row"><button class="w-primary" data-action="compose-path" ${!state.pathSelection.length||state.pathBusy?'disabled':''}>${state.pathBusy?'Preparazione…':'Crea ricerca enciclopedica'}</button><span class="w-small">${state.pathSelection.length} voci selezionate · modificabili anche dopo l’apertura</span></div></section>`:''}<div class="w-explore-categories">${categories.filter(c=>state.exploreCategory==='all'||c.id===state.exploreCategory).map((c,i)=>`<section class="w-explore-category"><div class="w-category-heading"><span aria-hidden="true">${String(categories.indexOf(c)+1).padStart(2,'0')}</span><div><h2>${esc(c.title)}</h2><p class="w-small">${esc(c.description)}</p></div></div><div class="w-path-grid">${c.paths.map(p=>`<button class="w-path-card" data-path="${esc(p.id)}"><strong>${esc(p.title)}</strong><span>${esc(p.question)}</span><small>${p.topics.map(esc).join(' · ')}</small><b>Esplora il percorso ↗</b></button>`).join('')}</div></section>`).join('')}</div><p class="w-small">Percorsi proposti da Wiki22, non una classificazione automatica di tutta la biblioteca. Ogni ricerca usa solo le fonti disponibili nelle librerie attive.</p></section>`;
  }
  async function openPath(id){
    const generation=++state.generation;message('Cerco le voci nelle librerie selezionate…');const result=await api('explore/resolve',{path_id:id,...scope()});if(generation!==state.generation)return;
    state.explorePath=result;state.pathSelection=result.rows.slice(0,12).map((_,i)=>i);state.pathBusy=false;renderExplore();message('');content.querySelector('.w-path-preview').scrollIntoView({block:'start',behavior:'smooth'});
  }
  async function composePath(){
    if(state.pathBusy||!state.pathSelection.length)return;const generation=++state.generation;state.pathBusy=true;renderExplore();message('Preparo la lettura con le fonti selezionate…');
    try{const result=await api('research',{documents:state.pathSelection.map(i=>reference(state.explorePath.rows[i])),...scope()});if(generation!==state.generation)return;
      resetKeywords();state.research=result;state.document=null;state.researchPage=0;state.researchNote=null;state.researchView='reading';state.view='research';render();message('');root.querySelector('#w-search').value='';root.querySelector('.w-main').scrollIntoView({block:'start'});
    }finally{state.pathBusy=false;if(generation===state.generation&&state.view==='explore')renderExplore();}
  }
  async function operation(name,value={}){return poll((await api(name,value)).job);}
  async function showGraph(kind='ENTITÀ',node=null){
    const topic=root.querySelector('#w-graph-topic')?.value.trim()||state.document?.title||state.query;
    if(!topic){state.view='graph';state.graph=null;render();return;}
    const generation=++state.generation;message('Leggo i collegamenti nelle librerie selezionate…');
    const value=await operation('graph',{topic,kind,node,...scope()});
    if(generation!==state.generation)return;state.graph=value;state.view='graph';render();message('');
  }
  function renderGraph(){const g=state.graph;
    content.innerHTML=`<section class="w-page"><div class="w-breadcrumb">MEMIDX · LOCO</div><h1>Collegamenti nelle fonti</h1><p>Esplora entità, temi, relazioni e date estratti dai passaggi delle librerie selezionate.</p><div class="w-row"><label>Argomento<input id="w-graph-topic" maxlength="240" value="${esc(g?.topic||state.document?.title||state.query)}"></label><button data-action="graph-search">Esplora collegamenti</button>${state.document?'<button data-action="back-reading">← Lettura</button>':''}</div>${g?`<p class="w-small">${g.stats.evidence_examined} passaggi esaminati · al massimo ${g.stats.candidate_limit}. È una mappa locale dei risultati, non di tutta la biblioteca.</p><div class="w-actions">${g.kinds.map(k=>`<button data-kind="${esc(k)}" aria-pressed="${g.kind===k}">${esc(k)}</button>`).join('')}</div><div class="w-graph-grid"><div class="w-node-list">${g.nodes.map(n=>`<button data-node="${esc(n.id)}" aria-pressed="${g.node===n.id}">${esc(n.label)}</button>`).join('')||'<p>Nessun elemento riconosciuto in questa categoria.</p>'}${g.total_nodes>120?'<p>Primi 120 elementi. Restringi l’argomento.</p>':''}</div><div>${g.evidence?`<h3>Passaggi che documentano il collegamento</h3>${g.evidence.map(e=>`<blockquote><p>${esc(e.text)}</p><footer>${esc(e.title)} · ${esc(e.library_name||names([e.library_id]))}<details><summary>Provenienza</summary><small>${esc(e.source_ref)}<br>${esc(e.evidence_id)}</small></details></footer></blockquote>`).join('')}<h3>Continua da qui</h3><div class="w-topiclist">${g.connections.map(c=>`<button data-node="${esc(c.node.id)}">${esc(c.node.label)} · ${esc(c.relation)}</button>`).join('')}</div>`:'<p>Scegli un elemento per leggere le fonti e seguirne i collegamenti.</p>'}</div></div>`:''}</section>`;
  }
  async function showMemory(){const generation=++state.generation;message('Verifico la memoria locale…');const m=await operation('memory');if(generation!==state.generation)return;state.memory=m;state.view='memory';render();message('');}
  function renderMemory(){const m=state.memory;
    content.innerHTML=`<section class="w-page"><div class="w-breadcrumb">MEM · LANG001 · Reflection</div><h1>Memoria e apprendimento</h1><p>Lo scaffale conserva le tue letture. Qui trovi i passaggi realmente osservati dal motore 22, con la loro provenienza.</p><label class="w-setting"><input id="w-learning" type="checkbox" ${state.prefs.automatic_learning?'checked':''}>Osserva automaticamente le voci che apro</label><label class="w-setting">Passaggi per lettura<select id="w-budget">${[1,3,8].map(n=>`<option value="${n}" ${state.prefs.learning_budget===n?'selected':''}>${n}</option>`).join('')}</select></label><p class="w-small">L’attivazione riguarda le prossime aperture. La memoria è locale, limitata e deduplicata. Non acquisisce automaticamente tutta Wikipedia.</p>${m?`<div class="w-metrics"><div><strong>${m.observations}</strong><span>Passaggi osservati</span></div><div><strong>${(m.bytes/1024).toFixed(1)} KB</strong><span>Osservazioni salvate</span></div><div><strong>${m.metrics.FORME_LESSICALI}</strong><span>Forme lessicali osservate</span></div><div><strong>${m.metrics.IPOTESI_LESSICALI}</strong><span>Ipotesi lessicali</span></div></div><p class="w-small">Le metriche del motore includono il lessico e gli esempi iniziali. I passaggi osservati indicano solo le nuove letture della tua enciclopedia.</p><p>${esc(m.note)}</p>${m.metrics.learning_limit_reached?'<p class="w-error">Budget della memoria raggiunto: le letture restano disponibili.</p>':''}<h3>Ultime osservazioni</h3>${m.recent.map(r=>`<blockquote><p>${esc(r.excerpt)}</p><small>${esc(r.provenance.library_id)} · ${esc(r.provenance.article_id)}<br>${esc(r.provenance.source)}</small></blockquote>`).join('')||'<p>Non ci sono ancora osservazioni. Apri una voce e scegli “Osserva questa fonte”.</p>'}<details><summary>Metriche tecniche del motore, non una misura di padronanza linguistica</summary><pre>${esc(JSON.stringify(m.metrics,null,2))}</pre></details>`:''}</section>`;
  }
  async function observeDocument(automatic=false){const d=state.document;if(!d)return;const result=await operation('observe',{document:reference(d),...scope(),budget:state.prefs.learning_budget||3});if(state.document===d)message(`${automatic?'Osservazione automatica':'Memoria'}: ${result.new_observations} nuovi passaggi della fonte. Le osservazioni non certificano un aumento di competenza.`);}
  function renderReason(){const r=state.reason;
    content.innerHTML=`<section class="w-page"><div class="w-breadcrumb">Ragionamento AI22 sulle fonti</div><h1>Interroga questa voce</h1><p class="w-deck">${esc(state.document?.title)}</p><p>Il motore cerca relazioni esplicite e applica le regole native disponibili. Se la domanda o la prova non sono supportate, lo dichiara.</p><label>Domanda<input id="w-reason-question" maxlength="500" value="${esc(state.reasonQuestion||'')}" placeholder="Ad esempio: che cosa afferma la fonte su…"></label><div class="w-actions"><button data-action="reason-submit">Verifica nelle fonti</button><button data-action="back-reading">← Lettura</button></div>${r?`<h3>${esc(r.STATO||'Esito')}</h3><p>${esc(r.RISPOSTA||r.VALORE||r.MOTIVO||'')}</p>${(r.FONTI||[]).map(f=>`<blockquote><p>${esc(f.testo)}</p><small>${esc(f.article_title)} · ${esc(f.provenance?.source)}</small></blockquote>`).join('')}<details><summary>Passaggi della verifica e limiti</summary><pre>${esc(JSON.stringify(r,null,2))}</pre></details>`:''}</section>`;
  }
  async function reasonSubmit(){const question=root.querySelector('#w-reason-question').value.trim(),d=state.document;state.reasonQuestion=question;const generation=++state.generation;message('Verifico le relazioni documentate…');const r=await operation('reason',{document:reference(d),question,...scope()});if(generation!==state.generation)return;state.reason=r;renderReason();message('');}
  function renderDiagnosis(){const d=state.diagnosis;
    content.innerHTML=`<section class="w-page"><div class="w-breadcrumb">SELF001 · CAP001 · STATE001</div><h1>Diagnosi di Wiki22</h1><p>Prove locali sui componenti e sulle capacità effettivamente verificate. Nessun voto QI o livello A1–C2 viene ricavato dal numero di parole memorizzate.</p><button data-action="diagnose" ${state.diagnosing?'disabled':''}>${state.diagnosing?'Verifica in corso…':'Esegui le prove tecniche'}</button>${d?`<p class="w-small">Eseguita: ${esc(new Date(d.at).toLocaleString('it-IT'))}</p><div class="w-metrics"><div><strong>${d.probe_pass}/${d.probe_total}</strong><span>Prove superate</span></div><div><strong>${d.verified_capabilities}</strong><span>Capacità con prova</span></div><div><strong>${d.components}</strong><span>Componenti rilevati</span></div></div><p>${esc(d.note)}</p><details><summary>Capacità, ricevute e impronta del codice verificato</summary><pre>${esc(JSON.stringify(d,null,2))}</pre></details>`:'<p>Avvia la verifica per ottenere una misura aggiornata del codice installato.</p>'}</section>`;
  }
  async function runDiagnosis(){if(state.diagnosing)return;state.diagnosing=true;render();try{const d=await operation('diagnose');state.diagnosis=d;if(state.view==='diagnosis')render();message(`Diagnosi: ${d.probe_pass}/${d.probe_total} prove superate.`);}finally{state.diagnosing=false;if(state.view==='diagnosis')render();}}
  function reportHtml(){const r=state.importReport;return r?`<section class="w-import"><h3>Rapporto di importazione · ${esc(r.format)}</h3><p>${r.articles} voci create · ${r.report.filter(x=>x.status!=='IMPORTED').length} file non importati</p><details open><summary>Esito per file</summary><div class="w-report">${r.report.map(f=>`<p><strong>${esc(f.file)}</strong> — ${f.status==='IMPORTED'?'Convertito in 22CK':esc(f.reason)}${f.sha256?`<details><summary>Impronta originale</summary><small>${esc(f.sha256)}</small></details>`:''}</p>`).join('')}</div></details></section>`:'';}

  async function findComparison(){const generation=++state.generation;state.compareQuery=root.querySelector('#w-compare-query')?.value.trim()||state.document.title;message('Cerco nelle altre librerie selezionate…');const result=await api('search',{query:state.compareQuery,...scope(),limit:50});if(generation!==state.generation)return;state.compareChoices=result.rows.filter(r=>r.library_id!==state.document.library_id);state.compareSearched=true;render();message(result.next?'Sono mostrati i primi risultati: precisa il titolo per restringere la ricerca.':'');}
  async function startComparison(){if(!state.document){message('Apri prima una voce per confrontarla.',true);return;}++state.generation;state.view='compare';state.comparison=null;state.compareChoices=[];state.compareSearched=false;state.compareQuery=state.document.title;render();if(selected().length>1)await findComparison();}
  async function compareChoice(index){const generation=++state.generation;message('Confronto i testi e le fonti…');const result=await api('compare',{left:reference(state.document),right:reference(state.compareChoices[index]),...scope()});if(generation!==state.generation)return;state.comparison=result;state.combined=false;state.commonOnly=false;render();message('');}
  async function showTimeline(){
    const origin=state.view,docs=origin==='research'?state.research.documents:origin==='compare'&&state.comparison?[state.comparison.left,state.comparison.right]:state.document?[state.document]:[];
    if(!docs.length){message('Apri una voce o una ricerca per consultare le date citate.',true);return;}
    const generation=++state.generation;message('Ordino le date presenti nei testi…');const result=await api('timeline',{documents:docs.map(reference),...scope()});if(generation!==state.generation)return;
    state.timeline=result;state.timelineRefs=docs.map(reference);state.timelineDraft={source:'current',era:'1'};state.timelineBusy=false;state.timelineOrigin=origin;state.timelineMode=result.highlights.length?'horizontal':'list';state.view='timeline';render();message('');root.querySelector('.w-main').scrollIntoView({block:'start'});
  }

  async function clicked(e){const b=e.target.closest('button');if(!b||!root.contains(b))return;
    if(b.hasAttribute('data-lib-remove'))return manageLibrary(Number(b.dataset.libRemove),'remove');
    if(b.hasAttribute('data-lib-restore'))return manageLibrary(Number(b.dataset.libRestore),'restore');
    if(b.hasAttribute('data-lib-rename'))return manageLibrary(Number(b.dataset.libRename),'rename');
    if(b.dataset.placeTopic){searchInput.value=b.dataset.placeTopic;return searchPlaces(b.dataset.placeTopic);}
    if(b.hasAttribute('data-place-choice'))return resolvePlace(Number(b.dataset.placeChoice));
    if(b.hasAttribute('data-place-read'))return openArticle(state.places.rows[Number(b.dataset.placeRead)]);
    if(b.dataset.action==='compose-place')return composePlace();
    if(b.dataset.action==='date-month'||b.dataset.action==='date-year'){content.querySelector('#w-date-day').value='';if(b.dataset.action==='date-year')content.querySelector('#w-date-month').value='';return findTimelineDate();}
    if(b.dataset.action==='reset-comfort')return saveComfort({palette:'paper',reading_font:'serif',line_spacing:'normal',font_size:17,columns:true});
    if(b.dataset.action==='calendar-start'){calendarStart();return;}
    if(b.dataset.action==='date-reset')return findTimelineDate(true);
    if(b.hasAttribute('data-focus-keyword'))return focusKeyword(Number(b.dataset.focusKeyword));
    if(b.dataset.action==='return-research'){++state.generation;state.view='research';render();message('');return;}
    if(b.dataset.action==='apply-depth'){state.view='research';render();return changeKeywords(researchRefs(),state.prefs.research_depth);}
    if(b.dataset.action==='research-reading'||b.dataset.action==='research-map'){state.researchView=b.dataset.action==='research-map'?'map':'reading';renderResearch();content.querySelector(state.researchView==='map'?'.w-mindmap':'.w-reading-position').scrollIntoView({block:'start',behavior:'smooth'});return;}
    if(b.hasAttribute('data-map-note')){const n=Number(b.dataset.mapNote);state.researchPage=state.research.pages.findIndex(p=>p.some(b=>b.sentences.some(s=>s.note===n)));state.researchNote=n;state.researchView='reading';renderResearch();content.querySelector('.w-source').scrollIntoView({block:'nearest',behavior:'smooth'});content.querySelector('.w-source').focus({preventScroll:true});return;}
    if(b.dataset.category){++state.generation;state.exploreCategory=b.dataset.category;state.explorePath=null;renderExplore();message('');return;}
    if(b.dataset.path)return openPath(b.dataset.path);
    if(b.hasAttribute('data-path-article'))return openArticle(state.explorePath.rows[Number(b.dataset.pathArticle)]);
    if(b.dataset.timelineMode){state.timelineMode=b.dataset.timelineMode;renderTimeline();return;}
    if(b.dataset.timelineScroll){content.querySelector('.w-time-track').scrollBy({left:Number(b.dataset.timelineScroll)*340,behavior:'smooth'});return;}
    if(b.dataset.action==='compose-path')return composePath();
    if(b.dataset.action==='timeline-back'){++state.generation;state.view=state.timelineOrigin||'article';render();return;}
    if(b.hasAttribute('data-keyword-remove'))return changeKeywords(researchRefs().filter((r,i)=>i!==Number(b.dataset.keywordRemove)));
    if(b.hasAttribute('data-keyword-add')){const r=state.keywordRows[Number(b.dataset.keywordAdd)];if(r&&!state.research.documents.some(x=>shelfKey(x)===shelfKey(r)))return changeKeywords([...researchRefs(),reference(r)]);return;}
    if(b.hasAttribute('data-remove-shelf')){const r=state.shelf[Number(b.dataset.removeShelf)];return removeShelf([{kind:'article',library_id:r.library_id,article_id:r.article_id}]);}
    if(b.hasAttribute('data-remove-research'))return removeShelf([{kind:'research',id:state.researches[Number(b.dataset.removeResearch)].id}]);
    if(b.hasAttribute('data-open-research'))return composeResearch(state.researches[Number(b.dataset.openResearch)]);
    if(b.hasAttribute('data-research-page'))return turnResearch(Number(b.dataset.researchPage));
    if(b.hasAttribute('data-research-note')){state.researchNote=Number(b.dataset.researchNote);renderResearch();content.querySelector('.w-source').scrollIntoView({block:'nearest',behavior:'smooth'});return;}
    if(b.hasAttribute('data-research-original'))return openArticle(state.research.documents[Number(b.dataset.researchOriginal)]);
    if(b.dataset.alternative!==undefined){const row=state.suggestions[Number(b.dataset.alternative)];searchInput.value=row.title;return openArticle(row);}
    if(b.id==='w-searchbutton'){if(state.view==='places')return searchPlaces(searchInput.value);if(state.view==='research'){state.keywordQuery=searchInput.value;return findKeyword();}return search(searchInput.value);}
    if(b.hasAttribute('data-comparison'))return compareChoice(Number(b.dataset.comparison));
    if(b.dataset.kind)return showGraph(b.dataset.kind);
    if(b.dataset.node)return showGraph(state.graph.kind,b.dataset.node);
    if(b.dataset.downloadId){await api('catalog/start',{id:b.dataset.downloadId});return refreshCatalog();}
    if(b.dataset.probePick){const d=probeDraft();state.probePaths=d.paths;state.probeUrls=d.urls;state.probeName=d.name;const result=await operation('pick',{kind:b.dataset.probePick});if(result.path)state.probePaths=[state.probePaths,result.path].filter(Boolean).join('\n');if(state.view==='probe')render();return;}
    if(b.dataset.nav)return navigate(b.dataset.nav);
    if(b.hasAttribute('data-result'))return openArticle(state.rows[Number(b.dataset.result)]);
    if(b.hasAttribute('data-resume')){const r=state.shelf[Number(b.dataset.resume)];if(library(r.library_id)?.removed){navigate('libraries');message('Ripristina la libreria dal cestino per riaprire questa lettura.');return;}state.prefs.mode=r.scope.length===1?'SINGLE':'CUSTOM';state.prefs.ids=[...r.scope];await savePrefs();shell();return openArticle(r,r.page);}
    if(b.dataset.topic){root.querySelector('#w-search').value=b.dataset.topic;return search(b.dataset.topic);}
    if(b.dataset.prefix)return search(b.dataset.prefix,false,true);
    if(b.dataset.only){state.prefs.mode='SINGLE';state.prefs.ids=[b.dataset.only];await scopeChanged();return search('',false,true);}
    if(b.dataset.pick)return pick(b.dataset.pick);
    if(b.hasAttribute('data-page'))return turn(Number(b.dataset.page));
    if(b.dataset.note){state.note=Number(b.dataset.note);renderArticle();root.querySelector('.w-source').scrollIntoView({block:'nearest',behavior:'smooth'});return;}
    const action=b.dataset.action;
    if(action==='probe-scan')return scanProbe();
    if(action==='probe-create')return createProbe();
    if(action==='download-pause'){await api('catalog/pause');return refreshCatalog();}
    if(action==='find-keyword')return findKeyword();
    if(action==='extend-article')return extendArticle();
    if(action==='select-shelf'){const allowed=state.shelf.filter(r=>selected().includes(r.library_id));if(chosenShelf().length===allowed.length){state.shelfSelection=[];}else if(allowed.length>12){message('Scegli fino a 12 voci per ogni ricerca.',true);return;}else state.shelfSelection=allowed.map(shelfKey);renderShelf();return;}
    if(action==='remove-selected')return removeShelf(chosenShelf().map(r=>({kind:'article',library_id:r.library_id,article_id:r.article_id})));
    if(action==='undo-shelf')return undoShelf();
    if(action==='compose-research')return composeResearch();
    if(action==='save-research')return saveResearch();
    if(action==='export-research')return exportResearch();
    if(action==='close-research-note'){const n=state.researchNote;state.researchNote=null;renderResearch();content.querySelector('[data-research-note="'+n+'"]')?.focus();return;}
    if(action==='compare'||action==='choose-comparison')return startComparison();
    if(action==='find-comparison')return findComparison();
    if(action==='timeline')return showTimeline();
    if(action==='combined'){state.combined=!state.combined;render();return;}
    if(action==='common-only'){state.commonOnly=!state.commonOnly;render();return;}
    if(action==='back-reading'){++state.generation;state.view='article';message('');render();return;}
    if(action==='back-comparison'){++state.generation;state.view='compare';render();return;}

    if(action==='results'){++state.generation;state.view='search';render();return;}
    if(action==='more')return search(state.query,true,state.view==='explore');
    if(action==='bookmark')return bookmark();
    if(action==='previous')return turn(state.page-1);
    if(action==='next')return turn(state.page+1);
    if(action==='sources'){state.note=state.document.pages[state.page][0].sentences[0].note;renderArticle();root.querySelector('.w-source').scrollIntoView({block:'nearest',behavior:'smooth'});}
    if(action==='close-source'){state.note=null;renderArticle();}
    if(action==='import')return importLibrary();
    if(action==='graph-search')return showGraph();
    if(action==='observe')return observeDocument();
    if(action==='reason'){++state.generation;state.view='reason';state.reason=null;state.reasonQuestion='';render();return;}
    if(action==='reason-submit')return reasonSubmit();
    if(action==='diagnose')return runDiagnosis();
    if(action==='formats'){const f=await api('formats');message('Nativi: '+f.native.join(', ')+'. Convertitori: '+f.optional.map(x=>x.extension+' '+(x.available?'disponibile':'richiede '+x.converter)).join('; ')+'. '+f.note);return;}
    if(action==='export')return exportDocument();
  }
  root.addEventListener('submit',e=>{if(e.target.id==='w-date-form'){e.preventDefault();findTimelineDate();}});
  root.addEventListener('input',e=>{if(e.target.id.startsWith('w-date-'))state.timelineDraft=readDateDraft();});
  root.addEventListener('click',e=>{clicked(e).catch(err=>message(err.message,true));});
  root.addEventListener('change',e=>{(async()=>{
    if(e.target.hasAttribute('data-probe-source')){const set=new Set(state.probeSelected||[]);if(e.target.checked)set.add(e.target.dataset.probeSource);else set.delete(e.target.dataset.probeSource);state.probeSelected=[...set];return;}
    if(e.target.hasAttribute('data-place-check')){const i=Number(e.target.dataset.placeCheck),v=new Set(state.placeSelection);if(e.target.checked){if(v.size>=12){e.target.checked=false;message('Scegli fino a 12 voci.',true);return;}v.add(i);}else v.delete(i);state.placeSelection=[...v];renderPlaces();return;}
    if(e.target.id.startsWith('w-date-')){state.timelineDraft=readDateDraft();if(e.target.id==='w-date-month'){state.timelineDraft.day='';const day=content.querySelector('#w-date-day');day.value='';day.disabled=!e.target.value;}return;}
    if(e.target.id==='w-research-depth')return changeKeywords(researchRefs(),e.target.value);
    if(e.target.id==='w-default-depth'){const old=state.prefs.research_depth;state.prefs.research_depth=e.target.value;try{await savePrefs();message('Ampiezza predefinita salvata.');}catch(err){state.prefs.research_depth=old;settings();throw err;}return;}
    if(e.target.hasAttribute('data-path-check')){const i=Number(e.target.dataset.pathCheck),values=new Set(state.pathSelection);if(e.target.checked){if(values.size>=12){e.target.checked=false;message('Scegli fino a 12 voci.',true);return;}values.add(i);}else values.delete(i);state.pathSelection=[...values];renderExplore();return;}
    if(e.target.hasAttribute('data-shelf-check')){const row=state.shelf[Number(e.target.dataset.shelfCheck)],key=shelfKey(row);const values=new Set(state.shelfSelection);if(e.target.checked){if(values.size>=12){e.target.checked=false;message('Puoi riunire fino a 12 voci in una ricerca.',true);return;}values.add(key);}else values.delete(key);state.shelfSelection=[...values];renderShelf();return;}
    if(e.target.id==='w-research-page')return turnResearch(Number(e.target.value)-1);
    if(e.target.id==='w-mode'){const previous=[...selected()];state.prefs.mode=e.target.value;if(state.prefs.mode==='SINGLE')state.prefs.ids=[previous[0]||state.libraries.find(l=>l.enabled)?.id].filter(Boolean);if(state.prefs.mode==='CUSTOM')state.prefs.ids=previous;return scopeChanged();}
    if(e.target.dataset.library){const id=e.target.dataset.library;if(state.prefs.mode==='SINGLE')state.prefs.ids=[id];else{const set=new Set(selected());e.target.checked?set.add(id):set.delete(id);state.prefs.mode='CUSTOM';state.prefs.ids=[...set];}return scopeChanged();}
    if(e.target.id==='w-columns')return saveComfort({columns:e.target.checked},e.target.id);
    if(e.target.id==='w-learning'){state.prefs.automatic_learning=e.target.checked;await savePrefs();return;}
    if(e.target.id==='w-budget'){state.prefs.learning_budget=Number(e.target.value);await savePrefs();return;}
    if(e.target.id==='w-font')return saveComfort({font_size:Number(e.target.value)},e.target.id);
    if(e.target.id==='w-reading-font')return saveComfort({reading_font:e.target.value},e.target.id);
    if(e.target.id==='w-line-spacing')return saveComfort({line_spacing:e.target.value},e.target.id);
    if(e.target.hasAttribute('data-palette'))return saveComfort({palette:e.target.value},e.target.id);
    if(e.target.id==='w-page-number')return turn(Number(e.target.value)-1);
  })().catch(err=>message(err.message,true));});
  const searchInput=root.querySelector('#w-search');
  let searchTimer=null;
  function cancelLiveSearch(){clearTimeout(searchTimer);searchTimer=null;}
  searchInput.addEventListener('input',()=>{
    if(state.view==='places'){cancelLiveSearch();++state.generation;searchTimer=setTimeout(()=>searchPlaces(searchInput.value).catch(e=>message(e.message,true)),250);return;}
    if(state.view==='research'){clearTimeout(keywordTimer);++keywordGeneration;state.keywordQuery=searchInput.value;state.keywordRows=[];state.keywordStatus=state.keywordQuery.trim().length<2?'Scrivi almeno due caratteri.':'';keywordResults();if(state.keywordQuery.trim().length>=2)keywordTimer=setTimeout(findKeyword,200);return;}
    cancelLiveSearch();++state.generation;
    const query=searchInput.value.trim();
    if(!query){state.query='';state.rows=[];state.suggestions=[];state.next=null;if(state.view==='search'){state.view='home';render();}return;}
    if(query.length<2||!selected().length)return;
    searchTimer=setTimeout(()=>search(query).catch(err=>message(err.message,true)),200);
  });
  searchInput.addEventListener('keydown',e=>{
    if(state.view==='places'){if(e.key==='Enter'){e.preventDefault();searchPlaces(searchInput.value).catch(e=>message(e.message,true));}return;}
    if(state.view==='research'){if(e.key==='Enter'){e.preventDefault();state.keywordQuery=searchInput.value;findKeyword();}if(e.key==='Escape'){clearTimeout(keywordTimer);++keywordGeneration;state.keywordRows=[];state.keywordStatus='';keywordResults();}if(e.key==='ArrowDown'){const first=content.querySelector('[data-keyword-add]:not(:disabled)');if(first){e.preventDefault();first.focus();}}return;}
    if(e.key==='Escape'){cancelLiveSearch();return;}
    if(e.key==='Enter'){e.preventDefault();search(e.target.value).catch(err=>message(err.message,true));}
    if(e.key==='ArrowDown'&&state.view==='search'){const first=content.querySelector('[data-result],[data-alternative]');if(first){e.preventDefault();first.focus();}}
  });
  bootstrap().catch(err=>{message(err.message,true);content.innerHTML='<section class="w-page"><h1>Wiki22</h1><p>Non è stato possibile aprire le librerie. Riapri l’applicazione.</p></section>';});
})();
